-- ══════════════ Cours DATA-01 — fondations de l'analyse de données ══════════════
--
-- Premier des deux cours du parcours « Data Analytics » : lire, nettoyer, explorer,
-- visualiser et interroger en SQL, sur cinq jeux de données réels d'Afrique de l'Ouest
-- (agriculture togolaise, mobile money sénégalais, microfinance béninoise).
--
-- ── Ce fichier est un artefact, pas la source ──
--
-- Le contenu vit dans shared/data-01.ts, typé et versionné. Ce SQL en est la projection,
-- produite par script/generate-data-01-sql.ts. Pour corriger une leçon, on édite le
-- TypeScript et l'on régénère — jamais l'inverse, sous peine de voir les deux diverger.
--
-- Les insertions de leçons sont gardées par un `not exists` sur (course_id, order_index) :
-- rejouer ce fichier ne crée pas de doublons, mais ne met pas non plus à jour une leçon
-- existante. Les UPDATE ci-dessous republient le contenu sans changer les IDs ni la progression.

insert into sms_courses (code, title, description, tools, level, total_lessons, order_index, is_published)
values ('DATA-01', 'Fondations de l''analyse de données : nettoyer, explorer, visualiser, interroger', 'Cinq semaines pour poser les gestes qui reviennent dans chaque mission d''analyste : inspecter un jeu de données brut, le nettoyer sans en fausser le sens, en tirer des statistiques qui tiennent, les mettre en image pour un décideur, et interroger une base relationnelle en SQL. Chaque semaine s''appuie sur un jeu de données synthétique — agriculture togolaise, mobile money sénégalais, banque de microfinance béninoise.',
  array['Python','Pandas','NumPy','Matplotlib/Seaborn','SQL']::text[], 'debutant', 5, 40, true)
on conflict (code) do update set
  title = excluded.title, description = excluded.description, tools = excluded.tools,
  level = excluded.level, total_lessons = excluded.total_lessons, is_published = excluded.is_published;

update sms_lessons l set title = 'Semaine 1 — Les fondations : un premier diagnostic de données simulées', content = '{"cells":[{"type":"md","content":"## Préparation et rythme de travail\n\nPrévoyez 10 à 15 heures par semaine, à ajuster selon votre niveau. Avant la semaine 1 : savoir gérer des fichiers, lire un CSV, calculer un pourcentage et exécuter une cellule Python. Si nécessaire, consacrez une semaine préparatoire à ces gestes. Neuf semaines constituent un parcours appliqué ; elles ne garantissent pas une expertise dans toutes les spécialités."},{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Ce qu''un analyste fait, concrètement\n\nUne coopérative de producteurs de maïs dans la région des Savanes, au Togo, tient un tableau de sa production depuis cinq ans : région, village, superficie cultivée, rendement obtenu, type de semence, quantité d''engrais, accès à l''irrigation, pluviométrie, type de sol, année, prix de vente. Le responsable veut savoir si ça vaut le coup d''investir dans l''irrigation l''an prochain.\n\nUn **Data Analyst** ne commence pas par un modèle ni par un graphique. Il commence par regarder ce qu''il a réellement entre les mains — combien de lignes, quelles colonnes, quels types de valeurs, quelles données manquent — avant de prétendre répondre à quoi que ce soit. C''est ce diagnostic, et rien d''autre, qui occupe cette première semaine.\n\nTrois métiers voisins qu''on confond souvent :\n\n- **Data Analyst** — répond à des questions métier avec les données existantes : rapports, tableaux de bord, recommandations ;\n- **Data Scientist** — construit des modèles prédictifs plus poussés, souvent sur des volumes plus grands ;\n- **Data Engineer** — construit et fiabilise les pipelines qui amènent la donnée jusqu''à l''analyste.\n\nCe parcours forme au premier métier. Les trois se recoupent sur le terrain, mais leurs livrables ne se ressemblent pas : un rapport et une recommandation, pas une infrastructure ni un modèle de recherche."},{"type":"callout","variant":"real","title":"Le jeu de données de la semaine","content":"togo_agriculture.csv — 1 200 observations, une ligne par exploitation suivie entre 2019 et 2023, dans cinq régions du Togo (Maritime, Plateaux, Centrale, Kara, Savanes). Onze colonnes : région, village, superficie (ha), rendement (tonnes/ha), type de semence, engrais NPK (kg), accès à l''irrigation, pluviométrie (mm), type de sol, année, prix de vente (FCFA). Deux colonnes portent de vraies valeurs manquantes — 48 sur 1 200, soit 4 % — sans qu''on vous le dise à l''avance : le repérer fait partie de l''exercice."},{"type":"md","content":"## Types de données : la première question à se poser sur CHAQUE colonne\n\nAvant tout calcul, une colonne se classe dans l''une de ces familles :\n\n| Famille | Ce que c''est | Exemple dans le fichier |\n|---|---|---|\n| Quantitative continue | Un nombre qui peut prendre n''importe quelle valeur dans un intervalle | `rendement_tonne_ha` (2,45, 3,1, 0,72…) |\n| Quantitative discrète | Un nombre qui ne prend que des valeurs entières | `annee` (2019, 2020…) |\n| Qualitative nominale | Une catégorie sans ordre naturel | `region` (Maritime, Kara…), `type_sol` |\n| Qualitative ordinale | Une catégorie avec un ordre | un niveau d''éducation (aucun < primaire < secondaire) — absent de ce fichier, présent dans celui de la semaine 7 |\n| Binaire | Deux valeurs seulement, souvent 0/1 | `acces_irrigation` |\n\nCe classement n''est pas académique : il décide de ce qu''on a le droit de calculer. Une moyenne sur `region` ne veut rien dire — ce n''est pas un nombre, c''est une étiquette. Une moyenne sur `rendement_tonne_ha`, si. Confondre les deux est l''erreur la plus fréquente d''un débutant, et celle qui produit les résultats les plus absurdes sans qu''aucun message d''erreur ne prévienne."},{"type":"code","lang":"python","code":"import pandas as pd\n\n# Échantillon représentatif du fichier togo_agriculture.csv (le fichier complet,\n# 1200 lignes, est dans le dataset à télécharger plus bas).\ncoop = pd.DataFrame({\n    \"region\":      [\"Savanes\", \"Kara\", \"Plateaux\", \"Maritime\", \"Centrale\",\n                    \"Savanes\", \"Plateaux\", \"Kara\", \"Maritime\", \"Centrale\"],\n    \"superficie_ha\":      [1.2, 2.8, 3.5, 0.9, 4.1, 1.8, 2.2, 3.9, 1.1, 2.6],\n    \"rendement_tonne_ha\": [1.6, 2.7, 3.1, 2.3, 2.0, 1.8, 3.4, 2.5, 2.6, 2.1],\n    \"type_semence\":   [\"Traditionnelle\", \"Hybride\", \"Améliorée\", \"OPV\",\n                       \"Traditionnelle\", \"Hybride\", \"Améliorée\", \"OPV\",\n                       \"Hybride\", \"Traditionnelle\"],\n    \"acces_irrigation\": [0, 1, 1, 0, 0, 0, 1, 0, 1, 0],\n    \"annee\":          [2021, 2022, 2023, 2020, 2019, 2022, 2023, 2021, 2020, 2022],\n})\n\nprint(\"Dimensions :\", coop.shape)\nprint(\"\\nTypes détectés par pandas :\")\nprint(coop.dtypes)","output":"Dimensions : (10, 6)\n\nTypes détectés par pandas :\nregion                 object\nsuperficie_ha         float64\nrendement_tonne_ha    float64\ntype_semence           object\nacces_irrigation        int64\nannee                   int64"},{"type":"md","content":"Remarquez : pandas dit `object` pour `region` et `type_semence` — c''est ainsi qu''il nomme le texte, pas une famille au sens de notre tableau. `acces_irrigation` sort en `int64` alors qu''il ne contient que 0 et 1 : pour pandas c''est un nombre entier ordinaire, pas un binaire — c''est à l''analyste de savoir qu''une moyenne dessus (`coop.acces_irrigation.mean()`) donne une **proportion** (la part d''exploitations irriguées), pas une grandeur physique.\n\n## Les quatre commandes qui ouvrent toute analyse\n\n- `.shape` — un couple (lignes, colonnes). Le premier chiffre à connaître, toujours ;\n- `.info()` — le type de chaque colonne et son nombre de valeurs non manquantes ;\n- `.describe()` — huit statistiques par colonne numérique : compte, moyenne, écart-type, minimum, les trois quartiles, maximum ;\n- `.head()` / `.tail()` — les premières ou dernières lignes, pour un contrôle visuel rapide.\n\nAucune de ces commandes ne « fait » de l''analyse. Elles disent seulement ce qu''on a réellement — et c''est déjà suffisant pour repérer un problème avant qu''il ne fausse tout le reste."},{"type":"code","lang":"python","code":"print(coop.describe().round(2))","output":"       superficie_ha  rendement_tonne_ha  acces_irrigation        annee\ncount      10.00               10.00             10.00        10.00\nmean        2.41                2.41              0.40      2021.30\nstd         1.11                0.57              0.52         1.34\nmin         0.90                1.60              0.00      2019.00\n25%         1.35                1.95              0.00      2020.25\n50%         2.40                2.40              0.00      2021.50\n75%         3.28                2.65              1.00      2022.00\nmax         4.10                3.40              1.00      2023.00"},{"type":"callout","variant":"tip","title":"Sur le fichier complet (1 200 lignes), pas sur cet échantillon","content":"Le rendement moyen réel du fichier togo_agriculture.csv est de 2,45 tonnes/ha (écart-type 0,60), avec un minimum de 0,72 et un maximum de 4,35. Les dix lignes ci-dessus servent à comprendre la MÉCANIQUE des commandes ; les exercices portant sur des chiffres précis se réfèrent au fichier complet, téléchargeable plus bas — c''est lui qu''il faut ouvrir pour les vérifier soi-même."},{"type":"md","content":"## Formuler une problématique analytique\n\n« Comprendre si l''irrigation vaut le coup » n''est pas une question de données, c''est une intention. Une question de données se construit en cinq temps :\n\n1. **Contexte** — une coopérative togolaise suit sa production depuis 2019 ;\n2. **Question précise** — les exploitations irriguées ont-elles un rendement moyen différent de celles qui ne le sont pas, à superficie comparable ?\n3. **Données nécessaires** — `rendement_tonne_ha`, `acces_irrigation`, `superficie_ha`, au minimum ;\n4. **Méthode** — comparer les moyennes de rendement entre les deux groupes (semaine 3) ;\n5. **Résultat attendu** — un chiffre, sa marge d''incertitude, et une phrase compréhensible par le responsable de la coopérative.\n\nSauter directement à l''étape 4 — choisir une méthode avant d''avoir formulé la question — est la façon la plus sûre de produire un résultat exact à une question que personne n''a posée."},{"type":"resource","title":"togo_agriculture.csv — jeu de données complet (1 200 lignes)","url":"/academy/data/datasets/togo_agriculture.csv","desc":"Le fichier synthétique de la semaine : cinq régions, cinq années, deux colonnes avec de vraies valeurs manquantes. Nécessaire pour le projet et pour vérifier les exercices ci-dessous.","provider":"LouisFarm"},{"type":"resource","title":"Notebook guidé — Semaine 1 : Foundations","url":"/academy/data/notebooks/S1_Foundations.ipynb","desc":"Un notebook Jupyter pas à pas sur le jeu de données complet : chargement, inspection, premières statistiques. À ouvrir dans Jupyter, JupyterLab ou Google Colab.","provider":"LouisFarm"},{"type":"resource","title":"utils_louisfarm.py — fichier compagnon, requis par tous les notebooks","url":"/academy/data/notebooks/utils_louisfarm.py","desc":"À télécharger UNE FOIS et à garder dans le même dossier que chacun des neuf notebooks du parcours (S1 à S9) : ils s''appuient tous dessus (sauf S4) pour régénérer, à l''identique, les jeux de données fournis en téléchargement.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 1 (diapositives)","url":"/academy/data/pptx/S1_Foundations.pptx","desc":"Le support utilisé pour présenter les fondations : rôle de l''analyste, types de données, framework de problématisation.","provider":"LouisFarm"},{"type":"exercise","id":"s1-shape","kind":"number","title":"Dimensions du fichier complet","prompt":"Après avoir chargé togo_agriculture.csv en entier avec pd.read_csv, combien de LIGNES compte le DataFrame (df.shape[0]) ?","answer":1200,"tolerance":0,"hint":"C''est le premier chiffre annoncé au début de cette leçon.","explain":"Le fichier compte exactement 1 200 observations — une ligne par exploitation suivie sur la période. df.shape renvoie (1200, 11) : 1 200 lignes, 11 colonnes."},{"type":"exercise","id":"s1-type-region","kind":"choice","title":"Classer une variable","prompt":"La colonne « region » (Maritime, Plateaux, Centrale, Kara, Savanes) est une variable de type :","opts":["Quantitative continue","Quantitative discrète","Qualitative nominale","Qualitative ordinale"],"answer":2,"hint":"Les cinq régions n''ont pas d''ordre naturel entre elles — aucune n''est « plus grande » qu''une autre au sens statistique.","explain":"« region » est qualitative nominale : ce sont des catégories, sans hiérarchie entre elles. Calculer une moyenne dessus n''a pas de sens ; on peut en revanche compter les effectifs par catégorie ou comparer une variable numérique entre régions (ce que fait la semaine 3)."},{"type":"exercise","id":"s1-manquants-pct","kind":"number","title":"Proportion de valeurs manquantes","prompt":"La colonne « pluviometrie_mm » compte 48 valeurs manquantes sur 1 200 lignes. Quel pourcentage cela représente-t-il ?","answer":4,"tolerance":0.5,"unit":"%","hint":"48 divisé par 1 200, multiplié par 100.","explain":"48 / 1 200 = 0,04, soit 4 %. La colonne « engrais_npk_kg » porte exactement le même nombre de valeurs manquantes (48) — un signe qu''elles proviennent probablement des mêmes lignes, à vérifier avec df[df.pluviometrie_mm.isna()]."},{"type":"exercise","id":"s1-region-max-rendement","kind":"choice","title":"Lire un classement","prompt":"En calculant le rendement MOYEN par région sur le fichier complet (df.groupby(''region'')[''rendement_tonne_ha''].mean()), quelle région arrive en tête ?","opts":["Savanes","Centrale","Plateaux","Maritime"],"answer":2,"hint":"Ce n''est pas la région la plus arrosée qui obtient le meilleur rendement moyen dans ce fichier.","explain":"Plateaux arrive en tête avec 2,97 tonnes/ha en moyenne, suivie de Kara (2,63), Maritime (2,49), Centrale (2,26) et enfin Savanes (1,90) — la région la moins favorisée sur cet indicateur, dans ce jeu de données précis."},{"type":"exercise","id":"s1-mean-rendement","kind":"number","title":"Une moyenne calculée pour de vrai","prompt":"Sur le fichier complet, quelle est la moyenne de « rendement_tonne_ha », arrondie à deux décimales ?","answer":2.45,"tolerance":0.02,"unit":"tonnes/ha","hint":"df[''rendement_tonne_ha''].mean().round(2)","explain":"2,45 tonnes/ha, pour un écart-type de 0,60 — donc une dispersion loin d''être négligeable autour de cette moyenne : le minimum est de 0,72 et le maximum de 4,35."},{"type":"exercise","id":"s1-describe-vs-head","kind":"text","title":"Deux commandes, deux usages","prompt":"En une phrase courte : quelle est la différence d''usage entre .head() et .describe() ?","answer":"resume statistique","accept":["statistiques","resume numerique","chiffres cles","synthese chiffree"],"hint":".head() montre des LIGNES ; .describe() montre des CALCULS.","explain":".head() affiche quelques lignes réelles du tableau, pour un contrôle visuel rapide. .describe() calcule un résumé statistique (moyenne, écart-type, quartiles…) de chaque colonne numérique — deux fonctions complémentaires, pas interchangeables."},{"type":"exercise","id":"s1-framework-ordre","kind":"choice","title":"L''ordre du raisonnement","prompt":"Dans le framework de problématisation vu cette semaine, que vient-il juste APRÈS « Question précise » ?","opts":["Résultat attendu","Méthode","Données nécessaires","Contexte"],"answer":2,"hint":"On ne choisit pas une méthode avant de savoir ce qu''on va lui donner à manger.","explain":"L''ordre est Contexte → Question précise → Données nécessaires → Méthode → Résultat attendu. Identifier les données AVANT la méthode évite de choisir un outil séduisant pour une donnée qu''on n''a pas."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nCréer une fiche de provenance : producteur, date, unité d’observation, licence, variables et limites. Distinguer fichier synthétique et enquête réelle. Livrable : dictionnaire de données et diagnostic de qualité."},{"type":"resource","title":"FAOSTAT — données agricoles documentées","url":"https://www.fao.org/faostat/en/","provider":"FAO","desc":"Choisir un pays, un produit, des années et des unités comparables. Les séries nationales ne remplacent pas une enquête individuelle."}]}'::jsonb
from sms_courses c where l.course_id = c.id and c.code = 'DATA-01' and l.order_index = 1;

insert into sms_lessons (course_id, title, content, type, points, order_index)
select c.id, 'Semaine 1 — Les fondations : un premier diagnostic de données simulées', '{"cells":[{"type":"md","content":"## Préparation et rythme de travail\n\nPrévoyez 10 à 15 heures par semaine, à ajuster selon votre niveau. Avant la semaine 1 : savoir gérer des fichiers, lire un CSV, calculer un pourcentage et exécuter une cellule Python. Si nécessaire, consacrez une semaine préparatoire à ces gestes. Neuf semaines constituent un parcours appliqué ; elles ne garantissent pas une expertise dans toutes les spécialités."},{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Ce qu''un analyste fait, concrètement\n\nUne coopérative de producteurs de maïs dans la région des Savanes, au Togo, tient un tableau de sa production depuis cinq ans : région, village, superficie cultivée, rendement obtenu, type de semence, quantité d''engrais, accès à l''irrigation, pluviométrie, type de sol, année, prix de vente. Le responsable veut savoir si ça vaut le coup d''investir dans l''irrigation l''an prochain.\n\nUn **Data Analyst** ne commence pas par un modèle ni par un graphique. Il commence par regarder ce qu''il a réellement entre les mains — combien de lignes, quelles colonnes, quels types de valeurs, quelles données manquent — avant de prétendre répondre à quoi que ce soit. C''est ce diagnostic, et rien d''autre, qui occupe cette première semaine.\n\nTrois métiers voisins qu''on confond souvent :\n\n- **Data Analyst** — répond à des questions métier avec les données existantes : rapports, tableaux de bord, recommandations ;\n- **Data Scientist** — construit des modèles prédictifs plus poussés, souvent sur des volumes plus grands ;\n- **Data Engineer** — construit et fiabilise les pipelines qui amènent la donnée jusqu''à l''analyste.\n\nCe parcours forme au premier métier. Les trois se recoupent sur le terrain, mais leurs livrables ne se ressemblent pas : un rapport et une recommandation, pas une infrastructure ni un modèle de recherche."},{"type":"callout","variant":"real","title":"Le jeu de données de la semaine","content":"togo_agriculture.csv — 1 200 observations, une ligne par exploitation suivie entre 2019 et 2023, dans cinq régions du Togo (Maritime, Plateaux, Centrale, Kara, Savanes). Onze colonnes : région, village, superficie (ha), rendement (tonnes/ha), type de semence, engrais NPK (kg), accès à l''irrigation, pluviométrie (mm), type de sol, année, prix de vente (FCFA). Deux colonnes portent de vraies valeurs manquantes — 48 sur 1 200, soit 4 % — sans qu''on vous le dise à l''avance : le repérer fait partie de l''exercice."},{"type":"md","content":"## Types de données : la première question à se poser sur CHAQUE colonne\n\nAvant tout calcul, une colonne se classe dans l''une de ces familles :\n\n| Famille | Ce que c''est | Exemple dans le fichier |\n|---|---|---|\n| Quantitative continue | Un nombre qui peut prendre n''importe quelle valeur dans un intervalle | `rendement_tonne_ha` (2,45, 3,1, 0,72…) |\n| Quantitative discrète | Un nombre qui ne prend que des valeurs entières | `annee` (2019, 2020…) |\n| Qualitative nominale | Une catégorie sans ordre naturel | `region` (Maritime, Kara…), `type_sol` |\n| Qualitative ordinale | Une catégorie avec un ordre | un niveau d''éducation (aucun < primaire < secondaire) — absent de ce fichier, présent dans celui de la semaine 7 |\n| Binaire | Deux valeurs seulement, souvent 0/1 | `acces_irrigation` |\n\nCe classement n''est pas académique : il décide de ce qu''on a le droit de calculer. Une moyenne sur `region` ne veut rien dire — ce n''est pas un nombre, c''est une étiquette. Une moyenne sur `rendement_tonne_ha`, si. Confondre les deux est l''erreur la plus fréquente d''un débutant, et celle qui produit les résultats les plus absurdes sans qu''aucun message d''erreur ne prévienne."},{"type":"code","lang":"python","code":"import pandas as pd\n\n# Échantillon représentatif du fichier togo_agriculture.csv (le fichier complet,\n# 1200 lignes, est dans le dataset à télécharger plus bas).\ncoop = pd.DataFrame({\n    \"region\":      [\"Savanes\", \"Kara\", \"Plateaux\", \"Maritime\", \"Centrale\",\n                    \"Savanes\", \"Plateaux\", \"Kara\", \"Maritime\", \"Centrale\"],\n    \"superficie_ha\":      [1.2, 2.8, 3.5, 0.9, 4.1, 1.8, 2.2, 3.9, 1.1, 2.6],\n    \"rendement_tonne_ha\": [1.6, 2.7, 3.1, 2.3, 2.0, 1.8, 3.4, 2.5, 2.6, 2.1],\n    \"type_semence\":   [\"Traditionnelle\", \"Hybride\", \"Améliorée\", \"OPV\",\n                       \"Traditionnelle\", \"Hybride\", \"Améliorée\", \"OPV\",\n                       \"Hybride\", \"Traditionnelle\"],\n    \"acces_irrigation\": [0, 1, 1, 0, 0, 0, 1, 0, 1, 0],\n    \"annee\":          [2021, 2022, 2023, 2020, 2019, 2022, 2023, 2021, 2020, 2022],\n})\n\nprint(\"Dimensions :\", coop.shape)\nprint(\"\\nTypes détectés par pandas :\")\nprint(coop.dtypes)","output":"Dimensions : (10, 6)\n\nTypes détectés par pandas :\nregion                 object\nsuperficie_ha         float64\nrendement_tonne_ha    float64\ntype_semence           object\nacces_irrigation        int64\nannee                   int64"},{"type":"md","content":"Remarquez : pandas dit `object` pour `region` et `type_semence` — c''est ainsi qu''il nomme le texte, pas une famille au sens de notre tableau. `acces_irrigation` sort en `int64` alors qu''il ne contient que 0 et 1 : pour pandas c''est un nombre entier ordinaire, pas un binaire — c''est à l''analyste de savoir qu''une moyenne dessus (`coop.acces_irrigation.mean()`) donne une **proportion** (la part d''exploitations irriguées), pas une grandeur physique.\n\n## Les quatre commandes qui ouvrent toute analyse\n\n- `.shape` — un couple (lignes, colonnes). Le premier chiffre à connaître, toujours ;\n- `.info()` — le type de chaque colonne et son nombre de valeurs non manquantes ;\n- `.describe()` — huit statistiques par colonne numérique : compte, moyenne, écart-type, minimum, les trois quartiles, maximum ;\n- `.head()` / `.tail()` — les premières ou dernières lignes, pour un contrôle visuel rapide.\n\nAucune de ces commandes ne « fait » de l''analyse. Elles disent seulement ce qu''on a réellement — et c''est déjà suffisant pour repérer un problème avant qu''il ne fausse tout le reste."},{"type":"code","lang":"python","code":"print(coop.describe().round(2))","output":"       superficie_ha  rendement_tonne_ha  acces_irrigation        annee\ncount      10.00               10.00             10.00        10.00\nmean        2.41                2.41              0.40      2021.30\nstd         1.11                0.57              0.52         1.34\nmin         0.90                1.60              0.00      2019.00\n25%         1.35                1.95              0.00      2020.25\n50%         2.40                2.40              0.00      2021.50\n75%         3.28                2.65              1.00      2022.00\nmax         4.10                3.40              1.00      2023.00"},{"type":"callout","variant":"tip","title":"Sur le fichier complet (1 200 lignes), pas sur cet échantillon","content":"Le rendement moyen réel du fichier togo_agriculture.csv est de 2,45 tonnes/ha (écart-type 0,60), avec un minimum de 0,72 et un maximum de 4,35. Les dix lignes ci-dessus servent à comprendre la MÉCANIQUE des commandes ; les exercices portant sur des chiffres précis se réfèrent au fichier complet, téléchargeable plus bas — c''est lui qu''il faut ouvrir pour les vérifier soi-même."},{"type":"md","content":"## Formuler une problématique analytique\n\n« Comprendre si l''irrigation vaut le coup » n''est pas une question de données, c''est une intention. Une question de données se construit en cinq temps :\n\n1. **Contexte** — une coopérative togolaise suit sa production depuis 2019 ;\n2. **Question précise** — les exploitations irriguées ont-elles un rendement moyen différent de celles qui ne le sont pas, à superficie comparable ?\n3. **Données nécessaires** — `rendement_tonne_ha`, `acces_irrigation`, `superficie_ha`, au minimum ;\n4. **Méthode** — comparer les moyennes de rendement entre les deux groupes (semaine 3) ;\n5. **Résultat attendu** — un chiffre, sa marge d''incertitude, et une phrase compréhensible par le responsable de la coopérative.\n\nSauter directement à l''étape 4 — choisir une méthode avant d''avoir formulé la question — est la façon la plus sûre de produire un résultat exact à une question que personne n''a posée."},{"type":"resource","title":"togo_agriculture.csv — jeu de données complet (1 200 lignes)","url":"/academy/data/datasets/togo_agriculture.csv","desc":"Le fichier synthétique de la semaine : cinq régions, cinq années, deux colonnes avec de vraies valeurs manquantes. Nécessaire pour le projet et pour vérifier les exercices ci-dessous.","provider":"LouisFarm"},{"type":"resource","title":"Notebook guidé — Semaine 1 : Foundations","url":"/academy/data/notebooks/S1_Foundations.ipynb","desc":"Un notebook Jupyter pas à pas sur le jeu de données complet : chargement, inspection, premières statistiques. À ouvrir dans Jupyter, JupyterLab ou Google Colab.","provider":"LouisFarm"},{"type":"resource","title":"utils_louisfarm.py — fichier compagnon, requis par tous les notebooks","url":"/academy/data/notebooks/utils_louisfarm.py","desc":"À télécharger UNE FOIS et à garder dans le même dossier que chacun des neuf notebooks du parcours (S1 à S9) : ils s''appuient tous dessus (sauf S4) pour régénérer, à l''identique, les jeux de données fournis en téléchargement.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 1 (diapositives)","url":"/academy/data/pptx/S1_Foundations.pptx","desc":"Le support utilisé pour présenter les fondations : rôle de l''analyste, types de données, framework de problématisation.","provider":"LouisFarm"},{"type":"exercise","id":"s1-shape","kind":"number","title":"Dimensions du fichier complet","prompt":"Après avoir chargé togo_agriculture.csv en entier avec pd.read_csv, combien de LIGNES compte le DataFrame (df.shape[0]) ?","answer":1200,"tolerance":0,"hint":"C''est le premier chiffre annoncé au début de cette leçon.","explain":"Le fichier compte exactement 1 200 observations — une ligne par exploitation suivie sur la période. df.shape renvoie (1200, 11) : 1 200 lignes, 11 colonnes."},{"type":"exercise","id":"s1-type-region","kind":"choice","title":"Classer une variable","prompt":"La colonne « region » (Maritime, Plateaux, Centrale, Kara, Savanes) est une variable de type :","opts":["Quantitative continue","Quantitative discrète","Qualitative nominale","Qualitative ordinale"],"answer":2,"hint":"Les cinq régions n''ont pas d''ordre naturel entre elles — aucune n''est « plus grande » qu''une autre au sens statistique.","explain":"« region » est qualitative nominale : ce sont des catégories, sans hiérarchie entre elles. Calculer une moyenne dessus n''a pas de sens ; on peut en revanche compter les effectifs par catégorie ou comparer une variable numérique entre régions (ce que fait la semaine 3)."},{"type":"exercise","id":"s1-manquants-pct","kind":"number","title":"Proportion de valeurs manquantes","prompt":"La colonne « pluviometrie_mm » compte 48 valeurs manquantes sur 1 200 lignes. Quel pourcentage cela représente-t-il ?","answer":4,"tolerance":0.5,"unit":"%","hint":"48 divisé par 1 200, multiplié par 100.","explain":"48 / 1 200 = 0,04, soit 4 %. La colonne « engrais_npk_kg » porte exactement le même nombre de valeurs manquantes (48) — un signe qu''elles proviennent probablement des mêmes lignes, à vérifier avec df[df.pluviometrie_mm.isna()]."},{"type":"exercise","id":"s1-region-max-rendement","kind":"choice","title":"Lire un classement","prompt":"En calculant le rendement MOYEN par région sur le fichier complet (df.groupby(''region'')[''rendement_tonne_ha''].mean()), quelle région arrive en tête ?","opts":["Savanes","Centrale","Plateaux","Maritime"],"answer":2,"hint":"Ce n''est pas la région la plus arrosée qui obtient le meilleur rendement moyen dans ce fichier.","explain":"Plateaux arrive en tête avec 2,97 tonnes/ha en moyenne, suivie de Kara (2,63), Maritime (2,49), Centrale (2,26) et enfin Savanes (1,90) — la région la moins favorisée sur cet indicateur, dans ce jeu de données précis."},{"type":"exercise","id":"s1-mean-rendement","kind":"number","title":"Une moyenne calculée pour de vrai","prompt":"Sur le fichier complet, quelle est la moyenne de « rendement_tonne_ha », arrondie à deux décimales ?","answer":2.45,"tolerance":0.02,"unit":"tonnes/ha","hint":"df[''rendement_tonne_ha''].mean().round(2)","explain":"2,45 tonnes/ha, pour un écart-type de 0,60 — donc une dispersion loin d''être négligeable autour de cette moyenne : le minimum est de 0,72 et le maximum de 4,35."},{"type":"exercise","id":"s1-describe-vs-head","kind":"text","title":"Deux commandes, deux usages","prompt":"En une phrase courte : quelle est la différence d''usage entre .head() et .describe() ?","answer":"resume statistique","accept":["statistiques","resume numerique","chiffres cles","synthese chiffree"],"hint":".head() montre des LIGNES ; .describe() montre des CALCULS.","explain":".head() affiche quelques lignes réelles du tableau, pour un contrôle visuel rapide. .describe() calcule un résumé statistique (moyenne, écart-type, quartiles…) de chaque colonne numérique — deux fonctions complémentaires, pas interchangeables."},{"type":"exercise","id":"s1-framework-ordre","kind":"choice","title":"L''ordre du raisonnement","prompt":"Dans le framework de problématisation vu cette semaine, que vient-il juste APRÈS « Question précise » ?","opts":["Résultat attendu","Méthode","Données nécessaires","Contexte"],"answer":2,"hint":"On ne choisit pas une méthode avant de savoir ce qu''on va lui donner à manger.","explain":"L''ordre est Contexte → Question précise → Données nécessaires → Méthode → Résultat attendu. Identifier les données AVANT la méthode évite de choisir un outil séduisant pour une donnée qu''on n''a pas."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nCréer une fiche de provenance : producteur, date, unité d’observation, licence, variables et limites. Distinguer fichier synthétique et enquête réelle. Livrable : dictionnaire de données et diagnostic de qualité."},{"type":"resource","title":"FAOSTAT — données agricoles documentées","url":"https://www.fao.org/faostat/en/","provider":"FAO","desc":"Choisir un pays, un produit, des années et des unités comparables. Les séries nationales ne remplacent pas une enquête individuelle."}]}'::jsonb, 'lesson', 100, 1
from sms_courses c where c.code = 'DATA-01'
  and not exists (select 1 from sms_lessons x where x.course_id = c.id and x.order_index = 1);

update sms_lessons l set title = 'Semaine 2 — Nettoyer un jeu de données sale, sans lui faire dire ce qu''il ne dit pas', content = '{"cells":[{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Un jeu de données synthétique n''arrive jamais propre\n\nsenegal_mobilemoney.csv rassemble 5 100 transactions de mobile money, saisies dans plusieurs villes du Sénégal sur dix-huit mois. Il n''a pas été sali artificiellement pour l''exercice : c''est la conséquence ordinaire de plusieurs agents, plusieurs villes, plusieurs habitudes de saisie, qui alimentent le même fichier. Trois problèmes s''y trouvent réellement :\n\n- les noms de ville existent en deux graphies — `DAKAR` et `Dakar` sont, pour un ordinateur, deux villes différentes, tant qu''on ne le lui dit pas ;\n- 100 identifiants de transaction sont dupliqués — la même ligne apparaît deux fois, ce qui compterait un même transfert comme deux s''il n''était pas repéré ;\n- deux colonnes (`genre_client`, `age_client`) portent 255 valeurs manquantes chacune.\n\nNettoyer ne veut pas dire supprimer tout ce qui gêne. Ça veut dire décider, colonne par colonne, ce que chaque anomalie signifie et ce qu''on en fait — et documenter la décision, pour qu''un collègue qui reprend le fichier sache pourquoi il a la forme qu''il a."},{"type":"callout","variant":"warning","title":"Le piège du nettoyage « au jugé »","content":"Supprimer toutes les lignes avec une valeur manquante (df.dropna()) est le réflexe le plus fréquent, et souvent le plus coûteux : sur ce fichier, ça ferait perdre 255 lignes sur 5 100, soit 5 % du volume, pour une seule colonne. Si l''analyse porte sur le montant des transactions — jamais manquant ici — ces 255 lignes n''avaient pas besoin de disparaître."},{"type":"md","content":"## Data profiling : l''état des lieux avant toute correction\n\nAvant de corriger quoi que ce soit, on mesure. Quatre dimensions suffisent pour un premier diagnostic :\n\n- **complétude** — combien de valeurs manquent, colonne par colonne ;\n- **unicité** — combien de lignes ou d''identifiants sont dupliqués ;\n- **cohérence** — les catégories d''une même colonne sont-elles écrites de façon homogène ;\n- **validité** — les valeurs respectent-elles ce qu''elles sont censées représenter (un montant ne devrait pas être négatif, une date ne devrait pas être dans le futur).\n\n`.duplicated()` renvoie une ligne de `True`/`False` par ligne du tableau ; `.sum()` derrière compte les `True`. `.isna().sum()` fait la même chose pour les valeurs manquantes, colonne par colonne."},{"type":"code","lang":"python","code":"import pandas as pd\n\n# Échantillon représentatif de senegal_mobilemoney.csv, avec ses vrais défauts.\nmm = pd.DataFrame({\n    \"id_transaction\": [\"TX001\", \"TX002\", \"TX003\", \"TX002\", \"TX004\", \"TX005\"],\n    \"ville\":  [\"DAKAR\", \"Dakar\", \"Thiès\", \"Dakar\", \"KAOLACK\", \"Kaolack\"],\n    \"montant_xof\": [38300.0, 18500.0, 271900.0, 18500.0, 46800.0, 8200.0],\n    \"genre_client\": [\"F\", \"M\", None, \"M\", \"F\", None],\n})\n\nprint(\"Doublons d''identifiant :\", mm[\"id_transaction\"].duplicated().sum())\nprint(\"Villes uniques (avant nettoyage) :\", sorted(mm[\"ville\"].unique()))\nprint(\"Valeurs manquantes par colonne :\")\nprint(mm.isna().sum())","output":"Doublons d''identifiant : 1\nVilles uniques (avant nettoyage) : [''Dakar'', ''DAKAR'', ''KAOLACK'', ''Kaolack'', ''Thiès'']\nValeurs manquantes par colonne :\nid_transaction    0\nville             0\nmontant_xof       0\ngenre_client      2"},{"type":"md","content":"## Standardiser les catégories, sans perdre l''information\n\n`.str.strip()` retire les espaces en trop en début et fin de texte. `.str.title()` met en forme « Dakar » proprement (première lettre en majuscule, reste en minuscule) — ou `.str.upper()` si l''on préfère tout en majuscules, l''important étant la même règle partout. `.drop_duplicates(subset=...)` retire les lignes dont l''identifiant se répète, en ne gardant que la première occurrence par défaut."},{"type":"code","lang":"python","code":"mm[\"ville\"] = mm[\"ville\"].str.strip().str.title()\nmm_propre = mm.drop_duplicates(subset=\"id_transaction\", keep=\"first\")\n\nprint(\"Villes uniques (après nettoyage) :\", sorted(mm_propre[\"ville\"].unique()))\nprint(\"Lignes avant :\", len(mm), \" / après suppression des doublons :\", len(mm_propre))","output":"Villes uniques (après nettoyage) : [''Dakar'', ''Kaolack'', ''Thiès'']\nLignes avant : 6  / après suppression des doublons : 5"},{"type":"callout","variant":"tip","title":"Sur le fichier complet, l''ordre de grandeur réel","content":"senegal_mobilemoney.csv contient 5 100 lignes, 100 identifiants de transaction dupliqués, et sept graphies différentes réparties sur les mêmes villes (deux casses par ville, sauf une). Après .str.strip().str.title() et suppression des doublons, il reste 5 000 transactions uniques et six villes bien orthographiées : Dakar, Diourbel, Kaolack, Saint-Louis, Tambacounda, Thiès, Ziguinchor — sept en réalité, une ville de plus qu''on n''en attendait au premier coup d''œil."},{"type":"md","content":"## Valeurs manquantes : ne jamais deviner pourquoi avant d''avoir vérifié\n\nTrois situations, trois traitements, et confondre l''une avec l''autre fausse l''analyse :\n\n- **MCAR** (manquant complètement au hasard) — la raison n''a aucun lien avec les autres variables. Un problème réseau qui a fait échouer la saisie de l''âge un jour donné, indépendamment du client ;\n- **MAR** (manquant dépendant d''une autre variable observée) — par exemple, si le genre manque plus souvent pour les transactions faites par guichet que par application ;\n- **MNAR** (manquant lié à la valeur elle-même) — un revenu très élevé délibérément non renseigné.\n\nDevant 255 âges manquants sur 5 100, la question à se poser n''est pas « quelle formule d''imputation utiliser », mais « est-ce que ces 255 lignes se ressemblent sur autre chose » — même opérateur, même zone, même type de transaction ? Ce n''est qu''après avoir regardé qu''on choisit : suppression si le volume est faible et la raison neutre, imputation par la médiane si la variable doit rester utilisable, ou conservation d''une catégorie « non renseigné » si l''absence elle-même est une information."},{"type":"resource","title":"senegal_mobilemoney.csv — jeu de données complet (5 100 lignes)","url":"/academy/data/datasets/senegal_mobilemoney.csv","desc":"Sept villes en plusieurs graphies, 100 identifiants dupliqués, 255 valeurs manquantes sur deux colonnes. Réutilisé en semaine 4 pour la visualisation.","provider":"LouisFarm"},{"type":"resource","title":"Notebook guidé — Semaine 2 : Data Wrangling","url":"/academy/data/notebooks/S2_DataWrangling.ipynb","desc":"Pipeline de nettoyage complet sur le fichier réel : profiling, doublons, casse des villes, valeurs manquantes.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 2 (diapositives)","url":"/academy/data/pptx/S2_DataWrangling.pptx","desc":"Data profiling, stratégies de traitement des valeurs manquantes, standardisation des catégories.","provider":"LouisFarm"},{"type":"exercise","id":"s2-doublons","kind":"number","title":"Compter les doublons réels","prompt":"Sur le fichier complet senegal_mobilemoney.csv, combien d''identifiants de transaction (« id_transaction ») sont dupliqués (df[''id_transaction''].duplicated().sum()) ?","answer":100,"tolerance":0,"hint":"C''est un chiffre rond, annoncé au début de la leçon.","explain":"100 identifiants sur 5 100 lignes sont des doublons — la même transaction enregistrée deux fois. Sans les retirer, un volume total de transactions serait surestimé d''environ 2 %."},{"type":"exercise","id":"s2-villes-avant","kind":"number","title":"Compter les graphies avant nettoyage","prompt":"Sur le fichier complet, combien de valeurs DISTINCTES la colonne « ville » contient-elle AVANT tout nettoyage de casse (sept vraies villes, mais comptées comment) ?","answer":14,"tolerance":0,"hint":"Chacune des sept villes existe sous deux graphies (ex. « DAKAR » et « Dakar »).","explain":"14 valeurs distinctes pour 7 villes réelles : chacune existe en tout-majuscules et en casse normale (« DAKAR »/« Dakar », « THIÈS »/« Thiès »…). C''est exactement le genre d''anomalie qu''un simple .unique() révèle avant même de commencer à corriger quoi que ce soit."},{"type":"exercise","id":"s2-mcar-mar","kind":"choice","title":"Identifier un mécanisme de valeur manquante","prompt":"Si l''on découvre que le genre du client manque presque uniquement pour les transactions faites via un opérateur en particulier (et jamais via les autres), de quel mécanisme s''agit-il ?","opts":["MCAR — manquant complètement au hasard","MAR — manquant dépendant d''une autre variable observée","MNAR — manquant lié à la valeur elle-même","Aucun des trois : c''est une erreur de calcul"],"answer":1,"hint":"L''absence est liée à une variable qu''on PEUT observer (l''opérateur) — pas à la valeur cachée elle-même.","explain":"C''est du MAR : l''absence dépend d''une variable observée (l''opérateur utilisé), qui n''est pas la variable manquante elle-même. Cette distinction change la stratégie : imputer par la médiane globale ignorerait que l''absence est concentrée, et fausserait les analyses par opérateur."},{"type":"exercise","id":"s2-dropna-consequence","kind":"text","title":"La conséquence d''un dropna() irréfléchi","prompt":"En une expression courte : quel est le principal risque de supprimer TOUTES les lignes contenant au moins une valeur manquante, sans vérifier quelles colonnes sont concernées ?","answer":"perte de donnees","accept":["perdre trop de lignes","perte de volume","supprimer des lignes valides","perte d''information"],"hint":"Une seule colonne à moitié vide peut faire disparaître des lignes par ailleurs parfaitement exploitables.","explain":"Le risque est de perdre des lignes par ailleurs valides, uniquement parce qu''UNE colonne (parfois non pertinente pour l''analyse en cours) leur manque. Sur ce fichier, dropna() sans discernement ferait perdre jusqu''à 5 % du volume pour une colonne (l''âge) qui n''intéresse pas toutes les analyses."},{"type":"exercise","id":"s2-villes-apres","kind":"number","title":"Après nettoyage","prompt":"Une fois .str.strip().str.title() (ou .str.upper()) appliqué de façon cohérente sur la colonne « ville » du fichier complet, combien de villes DISTINCTES reste-t-il ?","answer":7,"tolerance":0,"hint":"Le nombre de vraies villes derrière les 14 graphies.","explain":"7 villes réelles : Dakar, Diourbel, Kaolack, Saint-Louis, Tambacounda, Thiès, Ziguinchor. Standardiser la casse divise par deux le nombre de catégories apparentes, sans perdre une seule observation."},{"type":"exercise","id":"s2-quel-ordre","kind":"choice","title":"L''ordre des opérations","prompt":"Pour ne pas compter deux fois un même montant à cause d''un doublon ET d''une ville mal orthographiée, quel ordre est le plus sûr ?","opts":["Corriger les catégories, PUIS supprimer les doublons","Supprimer les doublons, PUIS corriger les catégories","L''ordre n''a strictement aucune importance","Corriger les catégories et supprimer les doublons doivent se faire dans la même instruction"],"answer":1,"hint":"Un doublon reste un doublon sur l''identifiant de transaction, que la ville soit bien ou mal écrite — mais autant s''assurer de ne pas introduire de nouveaux doublons en modifiant une clé.","explain":"Les deux ordres fonctionnent ici puisque .drop_duplicates(subset=''id_transaction'') ne regarde pas la colonne ville. Mais en général, la règle prudente est de dédupliquer sur un identifiant STABLE en premier, puis de nettoyer les colonnes de présentation (ville, libellés) — cela évite qu''une correction de texte ne masque ou ne crée artificiellement des doublons sur une colonne qu''on utiliserait par erreur comme clé."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nConserver le fichier brut, écrire un nettoyage reproductible et comparer les effectifs avant/après. Justifier chaque suppression et traiter les doublons sur une clé stable. Livrable : données nettoyées et journal des décisions."}]}'::jsonb
from sms_courses c where l.course_id = c.id and c.code = 'DATA-01' and l.order_index = 2;

insert into sms_lessons (course_id, title, content, type, points, order_index)
select c.id, 'Semaine 2 — Nettoyer un jeu de données sale, sans lui faire dire ce qu''il ne dit pas', '{"cells":[{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Un jeu de données synthétique n''arrive jamais propre\n\nsenegal_mobilemoney.csv rassemble 5 100 transactions de mobile money, saisies dans plusieurs villes du Sénégal sur dix-huit mois. Il n''a pas été sali artificiellement pour l''exercice : c''est la conséquence ordinaire de plusieurs agents, plusieurs villes, plusieurs habitudes de saisie, qui alimentent le même fichier. Trois problèmes s''y trouvent réellement :\n\n- les noms de ville existent en deux graphies — `DAKAR` et `Dakar` sont, pour un ordinateur, deux villes différentes, tant qu''on ne le lui dit pas ;\n- 100 identifiants de transaction sont dupliqués — la même ligne apparaît deux fois, ce qui compterait un même transfert comme deux s''il n''était pas repéré ;\n- deux colonnes (`genre_client`, `age_client`) portent 255 valeurs manquantes chacune.\n\nNettoyer ne veut pas dire supprimer tout ce qui gêne. Ça veut dire décider, colonne par colonne, ce que chaque anomalie signifie et ce qu''on en fait — et documenter la décision, pour qu''un collègue qui reprend le fichier sache pourquoi il a la forme qu''il a."},{"type":"callout","variant":"warning","title":"Le piège du nettoyage « au jugé »","content":"Supprimer toutes les lignes avec une valeur manquante (df.dropna()) est le réflexe le plus fréquent, et souvent le plus coûteux : sur ce fichier, ça ferait perdre 255 lignes sur 5 100, soit 5 % du volume, pour une seule colonne. Si l''analyse porte sur le montant des transactions — jamais manquant ici — ces 255 lignes n''avaient pas besoin de disparaître."},{"type":"md","content":"## Data profiling : l''état des lieux avant toute correction\n\nAvant de corriger quoi que ce soit, on mesure. Quatre dimensions suffisent pour un premier diagnostic :\n\n- **complétude** — combien de valeurs manquent, colonne par colonne ;\n- **unicité** — combien de lignes ou d''identifiants sont dupliqués ;\n- **cohérence** — les catégories d''une même colonne sont-elles écrites de façon homogène ;\n- **validité** — les valeurs respectent-elles ce qu''elles sont censées représenter (un montant ne devrait pas être négatif, une date ne devrait pas être dans le futur).\n\n`.duplicated()` renvoie une ligne de `True`/`False` par ligne du tableau ; `.sum()` derrière compte les `True`. `.isna().sum()` fait la même chose pour les valeurs manquantes, colonne par colonne."},{"type":"code","lang":"python","code":"import pandas as pd\n\n# Échantillon représentatif de senegal_mobilemoney.csv, avec ses vrais défauts.\nmm = pd.DataFrame({\n    \"id_transaction\": [\"TX001\", \"TX002\", \"TX003\", \"TX002\", \"TX004\", \"TX005\"],\n    \"ville\":  [\"DAKAR\", \"Dakar\", \"Thiès\", \"Dakar\", \"KAOLACK\", \"Kaolack\"],\n    \"montant_xof\": [38300.0, 18500.0, 271900.0, 18500.0, 46800.0, 8200.0],\n    \"genre_client\": [\"F\", \"M\", None, \"M\", \"F\", None],\n})\n\nprint(\"Doublons d''identifiant :\", mm[\"id_transaction\"].duplicated().sum())\nprint(\"Villes uniques (avant nettoyage) :\", sorted(mm[\"ville\"].unique()))\nprint(\"Valeurs manquantes par colonne :\")\nprint(mm.isna().sum())","output":"Doublons d''identifiant : 1\nVilles uniques (avant nettoyage) : [''Dakar'', ''DAKAR'', ''KAOLACK'', ''Kaolack'', ''Thiès'']\nValeurs manquantes par colonne :\nid_transaction    0\nville             0\nmontant_xof       0\ngenre_client      2"},{"type":"md","content":"## Standardiser les catégories, sans perdre l''information\n\n`.str.strip()` retire les espaces en trop en début et fin de texte. `.str.title()` met en forme « Dakar » proprement (première lettre en majuscule, reste en minuscule) — ou `.str.upper()` si l''on préfère tout en majuscules, l''important étant la même règle partout. `.drop_duplicates(subset=...)` retire les lignes dont l''identifiant se répète, en ne gardant que la première occurrence par défaut."},{"type":"code","lang":"python","code":"mm[\"ville\"] = mm[\"ville\"].str.strip().str.title()\nmm_propre = mm.drop_duplicates(subset=\"id_transaction\", keep=\"first\")\n\nprint(\"Villes uniques (après nettoyage) :\", sorted(mm_propre[\"ville\"].unique()))\nprint(\"Lignes avant :\", len(mm), \" / après suppression des doublons :\", len(mm_propre))","output":"Villes uniques (après nettoyage) : [''Dakar'', ''Kaolack'', ''Thiès'']\nLignes avant : 6  / après suppression des doublons : 5"},{"type":"callout","variant":"tip","title":"Sur le fichier complet, l''ordre de grandeur réel","content":"senegal_mobilemoney.csv contient 5 100 lignes, 100 identifiants de transaction dupliqués, et sept graphies différentes réparties sur les mêmes villes (deux casses par ville, sauf une). Après .str.strip().str.title() et suppression des doublons, il reste 5 000 transactions uniques et six villes bien orthographiées : Dakar, Diourbel, Kaolack, Saint-Louis, Tambacounda, Thiès, Ziguinchor — sept en réalité, une ville de plus qu''on n''en attendait au premier coup d''œil."},{"type":"md","content":"## Valeurs manquantes : ne jamais deviner pourquoi avant d''avoir vérifié\n\nTrois situations, trois traitements, et confondre l''une avec l''autre fausse l''analyse :\n\n- **MCAR** (manquant complètement au hasard) — la raison n''a aucun lien avec les autres variables. Un problème réseau qui a fait échouer la saisie de l''âge un jour donné, indépendamment du client ;\n- **MAR** (manquant dépendant d''une autre variable observée) — par exemple, si le genre manque plus souvent pour les transactions faites par guichet que par application ;\n- **MNAR** (manquant lié à la valeur elle-même) — un revenu très élevé délibérément non renseigné.\n\nDevant 255 âges manquants sur 5 100, la question à se poser n''est pas « quelle formule d''imputation utiliser », mais « est-ce que ces 255 lignes se ressemblent sur autre chose » — même opérateur, même zone, même type de transaction ? Ce n''est qu''après avoir regardé qu''on choisit : suppression si le volume est faible et la raison neutre, imputation par la médiane si la variable doit rester utilisable, ou conservation d''une catégorie « non renseigné » si l''absence elle-même est une information."},{"type":"resource","title":"senegal_mobilemoney.csv — jeu de données complet (5 100 lignes)","url":"/academy/data/datasets/senegal_mobilemoney.csv","desc":"Sept villes en plusieurs graphies, 100 identifiants dupliqués, 255 valeurs manquantes sur deux colonnes. Réutilisé en semaine 4 pour la visualisation.","provider":"LouisFarm"},{"type":"resource","title":"Notebook guidé — Semaine 2 : Data Wrangling","url":"/academy/data/notebooks/S2_DataWrangling.ipynb","desc":"Pipeline de nettoyage complet sur le fichier réel : profiling, doublons, casse des villes, valeurs manquantes.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 2 (diapositives)","url":"/academy/data/pptx/S2_DataWrangling.pptx","desc":"Data profiling, stratégies de traitement des valeurs manquantes, standardisation des catégories.","provider":"LouisFarm"},{"type":"exercise","id":"s2-doublons","kind":"number","title":"Compter les doublons réels","prompt":"Sur le fichier complet senegal_mobilemoney.csv, combien d''identifiants de transaction (« id_transaction ») sont dupliqués (df[''id_transaction''].duplicated().sum()) ?","answer":100,"tolerance":0,"hint":"C''est un chiffre rond, annoncé au début de la leçon.","explain":"100 identifiants sur 5 100 lignes sont des doublons — la même transaction enregistrée deux fois. Sans les retirer, un volume total de transactions serait surestimé d''environ 2 %."},{"type":"exercise","id":"s2-villes-avant","kind":"number","title":"Compter les graphies avant nettoyage","prompt":"Sur le fichier complet, combien de valeurs DISTINCTES la colonne « ville » contient-elle AVANT tout nettoyage de casse (sept vraies villes, mais comptées comment) ?","answer":14,"tolerance":0,"hint":"Chacune des sept villes existe sous deux graphies (ex. « DAKAR » et « Dakar »).","explain":"14 valeurs distinctes pour 7 villes réelles : chacune existe en tout-majuscules et en casse normale (« DAKAR »/« Dakar », « THIÈS »/« Thiès »…). C''est exactement le genre d''anomalie qu''un simple .unique() révèle avant même de commencer à corriger quoi que ce soit."},{"type":"exercise","id":"s2-mcar-mar","kind":"choice","title":"Identifier un mécanisme de valeur manquante","prompt":"Si l''on découvre que le genre du client manque presque uniquement pour les transactions faites via un opérateur en particulier (et jamais via les autres), de quel mécanisme s''agit-il ?","opts":["MCAR — manquant complètement au hasard","MAR — manquant dépendant d''une autre variable observée","MNAR — manquant lié à la valeur elle-même","Aucun des trois : c''est une erreur de calcul"],"answer":1,"hint":"L''absence est liée à une variable qu''on PEUT observer (l''opérateur) — pas à la valeur cachée elle-même.","explain":"C''est du MAR : l''absence dépend d''une variable observée (l''opérateur utilisé), qui n''est pas la variable manquante elle-même. Cette distinction change la stratégie : imputer par la médiane globale ignorerait que l''absence est concentrée, et fausserait les analyses par opérateur."},{"type":"exercise","id":"s2-dropna-consequence","kind":"text","title":"La conséquence d''un dropna() irréfléchi","prompt":"En une expression courte : quel est le principal risque de supprimer TOUTES les lignes contenant au moins une valeur manquante, sans vérifier quelles colonnes sont concernées ?","answer":"perte de donnees","accept":["perdre trop de lignes","perte de volume","supprimer des lignes valides","perte d''information"],"hint":"Une seule colonne à moitié vide peut faire disparaître des lignes par ailleurs parfaitement exploitables.","explain":"Le risque est de perdre des lignes par ailleurs valides, uniquement parce qu''UNE colonne (parfois non pertinente pour l''analyse en cours) leur manque. Sur ce fichier, dropna() sans discernement ferait perdre jusqu''à 5 % du volume pour une colonne (l''âge) qui n''intéresse pas toutes les analyses."},{"type":"exercise","id":"s2-villes-apres","kind":"number","title":"Après nettoyage","prompt":"Une fois .str.strip().str.title() (ou .str.upper()) appliqué de façon cohérente sur la colonne « ville » du fichier complet, combien de villes DISTINCTES reste-t-il ?","answer":7,"tolerance":0,"hint":"Le nombre de vraies villes derrière les 14 graphies.","explain":"7 villes réelles : Dakar, Diourbel, Kaolack, Saint-Louis, Tambacounda, Thiès, Ziguinchor. Standardiser la casse divise par deux le nombre de catégories apparentes, sans perdre une seule observation."},{"type":"exercise","id":"s2-quel-ordre","kind":"choice","title":"L''ordre des opérations","prompt":"Pour ne pas compter deux fois un même montant à cause d''un doublon ET d''une ville mal orthographiée, quel ordre est le plus sûr ?","opts":["Corriger les catégories, PUIS supprimer les doublons","Supprimer les doublons, PUIS corriger les catégories","L''ordre n''a strictement aucune importance","Corriger les catégories et supprimer les doublons doivent se faire dans la même instruction"],"answer":1,"hint":"Un doublon reste un doublon sur l''identifiant de transaction, que la ville soit bien ou mal écrite — mais autant s''assurer de ne pas introduire de nouveaux doublons en modifiant une clé.","explain":"Les deux ordres fonctionnent ici puisque .drop_duplicates(subset=''id_transaction'') ne regarde pas la colonne ville. Mais en général, la règle prudente est de dédupliquer sur un identifiant STABLE en premier, puis de nettoyer les colonnes de présentation (ville, libellés) — cela évite qu''une correction de texte ne masque ou ne crée artificiellement des doublons sur une colonne qu''on utiliserait par erreur comme clé."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nConserver le fichier brut, écrire un nettoyage reproductible et comparer les effectifs avant/après. Justifier chaque suppression et traiter les doublons sur une clé stable. Livrable : données nettoyées et journal des décisions."}]}'::jsonb, 'lesson', 100, 2
from sms_courses c where c.code = 'DATA-01'
  and not exists (select 1 from sms_lessons x where x.course_id = c.id and x.order_index = 2);

update sms_lessons l set title = 'Semaine 3 — De la donnée propre à l''information : statistiques et corrélation', content = '{"cells":[{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Un dataset propre ne parle pas tout seul\n\nLe fichier togo_agriculture.csv, une fois nettoyé, reste un tableau de 1 200 lignes. Cette semaine transforme ce tableau en réponses à des questions que se pose un programme de développement agricole : quels facteurs sont associés à un meilleur rendement ? Une région se distingue-t-elle vraiment, ou est-ce le hasard de l''échantillon ?\n\nTrois statistiques descriptives, et ce qu''elles disent :\n\n- **moyenne** — le centre de gravité arithmétique. Sensible aux valeurs extrêmes ;\n- **médiane** — la valeur qui sépare les données en deux moitiés égales. Insensible aux valeurs extrêmes ;\n- **écart-type** — la dispersion autour de la moyenne. Un écart-type élevé relativement à la moyenne dit que le « cas moyen » n''existe pas vraiment.\n\nSur le rendement du fichier complet : moyenne 2,45 t/ha, médiane 2,42 t/ha — les deux sont proches, signe d''une distribution assez symétrique, sans valeurs extrêmes qui tireraient la moyenne loin du centre."},{"type":"code","lang":"python","code":"import pandas as pd\n\nrendement = pd.Series([1.6, 2.7, 3.1, 2.3, 2.0, 1.8, 3.4, 2.5, 2.6, 2.1, 4.2, 0.9])\n\nprint(f\"Moyenne  : {rendement.mean():.2f}\")\nprint(f\"Médiane  : {rendement.median():.2f}\")\nprint(f\"Écart-type : {rendement.std():.2f}\")\nq1, q3 = rendement.quantile([0.25, 0.75])\nprint(f\"Q1={q1:.2f}  Q3={q3:.2f}  Écart interquartile (IQR)={q3-q1:.2f}\")","output":"Moyenne  : 2.43\nMédiane  : 2.40\nÉcart-type : 0.85\nQ1=1.88  Q3=2.78  Écart interquartile (IQR)=0.90"},{"type":"md","content":"## Corrélation : ce qu''un chiffre entre -1 et 1 dit, et ne dit pas\n\nLa corrélation de Pearson mesure la force d''une relation LINÉAIRE entre deux variables numériques. +1 : elles montent parfaitement ensemble. -1 : l''une monte quand l''autre descend, parfaitement. 0 : aucune relation linéaire détectable — ce qui n''exclut pas une relation d''une autre forme.\n\nSur le fichier complet, la corrélation entre `rendement_tonne_ha` et `pluviometrie_mm` vaut 0,26 : une relation positive, mais modeste. Celle avec `prix_vente_fcfa` vaut 0,88 — beaucoup plus forte."},{"type":"callout","variant":"warning","title":"0,88, et pourtant ce n''est pas ce qu''on croit","content":"Une corrélation de 0,88 entre le rendement et le PRIX DE VENTE est forte. Elle ne dit pas que produire plus fait monter le prix, ni l''inverse : sur ce fichier, les deux varient probablement ensemble parce qu''ils dépendent d''un facteur commun non mesuré ici (qualité de la récolte, année, dynamique du marché local). Un rendement élevé ne CAUSE pas mécaniquement un prix élevé — les deux avancent ensemble, ce qui est une observation, pas une explication."},{"type":"code","lang":"python","code":"import pandas as pd\n\n# Extrait illustrant la relation rendement / accès à l''irrigation.\ndf = pd.DataFrame({\n    \"acces_irrigation\":   [0, 1, 0, 1, 0, 0, 1, 0, 1, 0, 0, 1],\n    \"rendement_tonne_ha\": [1.6, 2.7, 2.3, 2.0, 1.8, 3.4, 2.5, 2.6, 2.1, 4.2, 0.9, 2.4],\n})\nprint(df.groupby(\"acces_irrigation\")[\"rendement_tonne_ha\"].agg([\"mean\", \"count\"]))","output":"                  mean  count\nacces_irrigation                \n0                 2.367      8\n1                 2.400      4"},{"type":"md","content":"Sur ce petit extrait, la différence entre irrigué et non irrigué est presque nulle. **Le fichier complet confirme cette surprise** : rendement moyen de 2,45 t/ha SANS irrigation contre 2,42 t/ha AVEC — une différence négligeable, et même dans le sens inverse de l''intuition. La corrélation numérique entre `acces_irrigation` et `rendement_tonne_ha` sur les 1 200 lignes est de -0,02 : quasi nulle.\n\nCe n''est pas une erreur du fichier, c''est un résultat à interpréter avec prudence : l''irrigation a pu être installée en priorité sur les parcelles les moins favorisées au départ (sol plus pauvre, pluviométrie plus faible) — un **facteur de confusion** qui masque un effet réel de l''irrigation, ou bien l''irrigation, dans cet échantillon précis, n''a simplement pas l''effet qu''on lui prête ailleurs. Les deux hypothèses restent ouvertes ; seule une comparaison à conditions égales (même type de sol, même région) permettrait de trancher — ce que ce niveau d''analyse ne fait pas encore."},{"type":"callout","variant":"tip","title":"Le paradoxe de Simpson, en une phrase","content":"Une relation peut s''inverser ou disparaître selon qu''on regarde les données globalement ou groupe par groupe. C''est exactement le risque illustré ci-dessus : conclure « l''irrigation ne sert à rien » sur la base d''une corrélation globale, sans avoir contrôlé le type de sol ou la région, serait aller plus vite que ce que les données permettent réellement d''affirmer."},{"type":"resource","title":"Notebook guidé — Semaine 3 : EDA & Statistics","url":"/academy/data/notebooks/S3_EDA_Statistics.ipynb","desc":"Statistiques descriptives, distributions, matrice de corrélation complète sur togo_agriculture.csv.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 3 (diapositives)","url":"/academy/data/pptx/S3_EDA_Statistics.pptx","desc":"Moyenne vs médiane, corrélation de Pearson, pièges de l''interprétation statistique.","provider":"LouisFarm"},{"type":"exercise","id":"s3-corr-prix","kind":"number","title":"Lire une matrice de corrélation","prompt":"Sur le fichier complet, la corrélation entre « rendement_tonne_ha » et « prix_vente_fcfa » est de :","answer":0.88,"tolerance":0.02,"hint":"Une des corrélations les plus fortes de tout le fichier — mais forte ne veut pas dire causale.","explain":"0,88 — une corrélation forte, mais qui ne prouve aucune causalité dans un sens ou dans l''autre. Les deux variables évoluent ensemble, probablement sous l''effet de facteurs communs non mesurés dans ce fichier (qualité de la saison, dynamique du marché)."},{"type":"exercise","id":"s3-causalite","kind":"choice","title":"L''erreur à ne pas commettre","prompt":"Une corrélation de 0,72 entre le montant des microcrédits accordés et le taux de remboursement, sur 500 emprunteurs sénégalais, permet de conclure que :","opts":["Donner de plus gros crédits AMÉLIORE mécaniquement le remboursement","Les deux variables évoluent ensemble dans cet échantillon, sans que cela prouve qu''une cause l''autre","Le remboursement CAUSE le montant du crédit accordé","Il n''existe aucune relation entre les deux variables"],"answer":1,"hint":"Une corrélation, même forte, ne distingue jamais laquelle des deux variables (si l''une des deux) est la cause.","explain":"Une corrélation de 0,72 dit que les deux variables évoluent ensemble dans cet échantillon — rien de plus. Une explication alternative plausible : les emprunteurs jugés les plus solides reçoivent à la fois de plus gros crédits ET remboursent mieux, un facteur commun (leur solvabilité) expliquant les deux, sans qu''aucune des deux variables ne cause l''autre."},{"type":"exercise","id":"s3-irrigation-effet","kind":"number","title":"Une surprise chiffrée","prompt":"Sur le fichier complet, quelle est la différence, en valeur absolue, entre le rendement moyen SANS irrigation et le rendement moyen AVEC irrigation (en tonnes/ha) ?","answer":0.03,"tolerance":0.02,"unit":"tonnes/ha","hint":"2,45 sans irrigation contre 2,42 avec — la différence est minuscule.","explain":"Environ 0,03 tonne/ha — une différence négligeable, presque dans le sens inverse de ce qu''on attendrait spontanément. Cela n''établit pas que l''irrigation est inutile : un facteur de confusion (les parcelles irriguées étant peut-être, au départ, les moins favorisées) peut masquer un effet réel."},{"type":"exercise","id":"s3-moyenne-mediane","kind":"text","title":"Ce que l''écart moyenne/médiane signale","prompt":"En une expression courte : que signale une GRANDE différence entre la moyenne et la médiane d''une variable ?","answer":"valeurs extremes","accept":["distribution asymetrique","valeurs aberrantes","asymetrie","queue lourde"],"hint":"La moyenne se laisse « tirer » par des valeurs très hautes ou très basses ; la médiane, non.","explain":"Un grand écart entre moyenne et médiane signale une distribution asymétrique, souvent due à quelques valeurs extrêmes qui tirent la moyenne loin du centre réel de la donnée. Sur le rendement togolais, moyenne (2,45) et médiane (2,42) sont proches : pas de signal de ce type ici."},{"type":"exercise","id":"s3-simpson","kind":"choice","title":"Reconnaître le paradoxe de Simpson","prompt":"Le paradoxe de Simpson décrit une situation où :","opts":["Une même variable a deux moyennes différentes selon la méthode de calcul","Une relation observée globalement s''inverse ou disparaît lorsqu''on regarde les données groupe par groupe","Un test statistique donne toujours le même résultat quel que soit l''échantillon","Une corrélation négative devient positive en changeant d''unité de mesure"],"answer":1,"hint":"C''est exactement le risque évoqué à propos de l''irrigation et du type de sol.","explain":"C''est la définition même du paradoxe : une tendance visible sur l''ensemble des données peut s''inverser une fois les données séparées par sous-groupe (ici, potentiellement, par type de sol ou par région). C''est pourquoi une corrélation globale se vérifie toujours, quand c''est possible, en la recalculant à l''intérieur de chaque sous-groupe pertinent."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nDécrire population, échantillon, valeurs manquantes et incertitude. Une association ne prouve pas une causalité. Livrable : note de deux pages avec trois constats et leurs limites."}]}'::jsonb
from sms_courses c where l.course_id = c.id and c.code = 'DATA-01' and l.order_index = 3;

insert into sms_lessons (course_id, title, content, type, points, order_index)
select c.id, 'Semaine 3 — De la donnée propre à l''information : statistiques et corrélation', '{"cells":[{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Un dataset propre ne parle pas tout seul\n\nLe fichier togo_agriculture.csv, une fois nettoyé, reste un tableau de 1 200 lignes. Cette semaine transforme ce tableau en réponses à des questions que se pose un programme de développement agricole : quels facteurs sont associés à un meilleur rendement ? Une région se distingue-t-elle vraiment, ou est-ce le hasard de l''échantillon ?\n\nTrois statistiques descriptives, et ce qu''elles disent :\n\n- **moyenne** — le centre de gravité arithmétique. Sensible aux valeurs extrêmes ;\n- **médiane** — la valeur qui sépare les données en deux moitiés égales. Insensible aux valeurs extrêmes ;\n- **écart-type** — la dispersion autour de la moyenne. Un écart-type élevé relativement à la moyenne dit que le « cas moyen » n''existe pas vraiment.\n\nSur le rendement du fichier complet : moyenne 2,45 t/ha, médiane 2,42 t/ha — les deux sont proches, signe d''une distribution assez symétrique, sans valeurs extrêmes qui tireraient la moyenne loin du centre."},{"type":"code","lang":"python","code":"import pandas as pd\n\nrendement = pd.Series([1.6, 2.7, 3.1, 2.3, 2.0, 1.8, 3.4, 2.5, 2.6, 2.1, 4.2, 0.9])\n\nprint(f\"Moyenne  : {rendement.mean():.2f}\")\nprint(f\"Médiane  : {rendement.median():.2f}\")\nprint(f\"Écart-type : {rendement.std():.2f}\")\nq1, q3 = rendement.quantile([0.25, 0.75])\nprint(f\"Q1={q1:.2f}  Q3={q3:.2f}  Écart interquartile (IQR)={q3-q1:.2f}\")","output":"Moyenne  : 2.43\nMédiane  : 2.40\nÉcart-type : 0.85\nQ1=1.88  Q3=2.78  Écart interquartile (IQR)=0.90"},{"type":"md","content":"## Corrélation : ce qu''un chiffre entre -1 et 1 dit, et ne dit pas\n\nLa corrélation de Pearson mesure la force d''une relation LINÉAIRE entre deux variables numériques. +1 : elles montent parfaitement ensemble. -1 : l''une monte quand l''autre descend, parfaitement. 0 : aucune relation linéaire détectable — ce qui n''exclut pas une relation d''une autre forme.\n\nSur le fichier complet, la corrélation entre `rendement_tonne_ha` et `pluviometrie_mm` vaut 0,26 : une relation positive, mais modeste. Celle avec `prix_vente_fcfa` vaut 0,88 — beaucoup plus forte."},{"type":"callout","variant":"warning","title":"0,88, et pourtant ce n''est pas ce qu''on croit","content":"Une corrélation de 0,88 entre le rendement et le PRIX DE VENTE est forte. Elle ne dit pas que produire plus fait monter le prix, ni l''inverse : sur ce fichier, les deux varient probablement ensemble parce qu''ils dépendent d''un facteur commun non mesuré ici (qualité de la récolte, année, dynamique du marché local). Un rendement élevé ne CAUSE pas mécaniquement un prix élevé — les deux avancent ensemble, ce qui est une observation, pas une explication."},{"type":"code","lang":"python","code":"import pandas as pd\n\n# Extrait illustrant la relation rendement / accès à l''irrigation.\ndf = pd.DataFrame({\n    \"acces_irrigation\":   [0, 1, 0, 1, 0, 0, 1, 0, 1, 0, 0, 1],\n    \"rendement_tonne_ha\": [1.6, 2.7, 2.3, 2.0, 1.8, 3.4, 2.5, 2.6, 2.1, 4.2, 0.9, 2.4],\n})\nprint(df.groupby(\"acces_irrigation\")[\"rendement_tonne_ha\"].agg([\"mean\", \"count\"]))","output":"                  mean  count\nacces_irrigation                \n0                 2.367      8\n1                 2.400      4"},{"type":"md","content":"Sur ce petit extrait, la différence entre irrigué et non irrigué est presque nulle. **Le fichier complet confirme cette surprise** : rendement moyen de 2,45 t/ha SANS irrigation contre 2,42 t/ha AVEC — une différence négligeable, et même dans le sens inverse de l''intuition. La corrélation numérique entre `acces_irrigation` et `rendement_tonne_ha` sur les 1 200 lignes est de -0,02 : quasi nulle.\n\nCe n''est pas une erreur du fichier, c''est un résultat à interpréter avec prudence : l''irrigation a pu être installée en priorité sur les parcelles les moins favorisées au départ (sol plus pauvre, pluviométrie plus faible) — un **facteur de confusion** qui masque un effet réel de l''irrigation, ou bien l''irrigation, dans cet échantillon précis, n''a simplement pas l''effet qu''on lui prête ailleurs. Les deux hypothèses restent ouvertes ; seule une comparaison à conditions égales (même type de sol, même région) permettrait de trancher — ce que ce niveau d''analyse ne fait pas encore."},{"type":"callout","variant":"tip","title":"Le paradoxe de Simpson, en une phrase","content":"Une relation peut s''inverser ou disparaître selon qu''on regarde les données globalement ou groupe par groupe. C''est exactement le risque illustré ci-dessus : conclure « l''irrigation ne sert à rien » sur la base d''une corrélation globale, sans avoir contrôlé le type de sol ou la région, serait aller plus vite que ce que les données permettent réellement d''affirmer."},{"type":"resource","title":"Notebook guidé — Semaine 3 : EDA & Statistics","url":"/academy/data/notebooks/S3_EDA_Statistics.ipynb","desc":"Statistiques descriptives, distributions, matrice de corrélation complète sur togo_agriculture.csv.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 3 (diapositives)","url":"/academy/data/pptx/S3_EDA_Statistics.pptx","desc":"Moyenne vs médiane, corrélation de Pearson, pièges de l''interprétation statistique.","provider":"LouisFarm"},{"type":"exercise","id":"s3-corr-prix","kind":"number","title":"Lire une matrice de corrélation","prompt":"Sur le fichier complet, la corrélation entre « rendement_tonne_ha » et « prix_vente_fcfa » est de :","answer":0.88,"tolerance":0.02,"hint":"Une des corrélations les plus fortes de tout le fichier — mais forte ne veut pas dire causale.","explain":"0,88 — une corrélation forte, mais qui ne prouve aucune causalité dans un sens ou dans l''autre. Les deux variables évoluent ensemble, probablement sous l''effet de facteurs communs non mesurés dans ce fichier (qualité de la saison, dynamique du marché)."},{"type":"exercise","id":"s3-causalite","kind":"choice","title":"L''erreur à ne pas commettre","prompt":"Une corrélation de 0,72 entre le montant des microcrédits accordés et le taux de remboursement, sur 500 emprunteurs sénégalais, permet de conclure que :","opts":["Donner de plus gros crédits AMÉLIORE mécaniquement le remboursement","Les deux variables évoluent ensemble dans cet échantillon, sans que cela prouve qu''une cause l''autre","Le remboursement CAUSE le montant du crédit accordé","Il n''existe aucune relation entre les deux variables"],"answer":1,"hint":"Une corrélation, même forte, ne distingue jamais laquelle des deux variables (si l''une des deux) est la cause.","explain":"Une corrélation de 0,72 dit que les deux variables évoluent ensemble dans cet échantillon — rien de plus. Une explication alternative plausible : les emprunteurs jugés les plus solides reçoivent à la fois de plus gros crédits ET remboursent mieux, un facteur commun (leur solvabilité) expliquant les deux, sans qu''aucune des deux variables ne cause l''autre."},{"type":"exercise","id":"s3-irrigation-effet","kind":"number","title":"Une surprise chiffrée","prompt":"Sur le fichier complet, quelle est la différence, en valeur absolue, entre le rendement moyen SANS irrigation et le rendement moyen AVEC irrigation (en tonnes/ha) ?","answer":0.03,"tolerance":0.02,"unit":"tonnes/ha","hint":"2,45 sans irrigation contre 2,42 avec — la différence est minuscule.","explain":"Environ 0,03 tonne/ha — une différence négligeable, presque dans le sens inverse de ce qu''on attendrait spontanément. Cela n''établit pas que l''irrigation est inutile : un facteur de confusion (les parcelles irriguées étant peut-être, au départ, les moins favorisées) peut masquer un effet réel."},{"type":"exercise","id":"s3-moyenne-mediane","kind":"text","title":"Ce que l''écart moyenne/médiane signale","prompt":"En une expression courte : que signale une GRANDE différence entre la moyenne et la médiane d''une variable ?","answer":"valeurs extremes","accept":["distribution asymetrique","valeurs aberrantes","asymetrie","queue lourde"],"hint":"La moyenne se laisse « tirer » par des valeurs très hautes ou très basses ; la médiane, non.","explain":"Un grand écart entre moyenne et médiane signale une distribution asymétrique, souvent due à quelques valeurs extrêmes qui tirent la moyenne loin du centre réel de la donnée. Sur le rendement togolais, moyenne (2,45) et médiane (2,42) sont proches : pas de signal de ce type ici."},{"type":"exercise","id":"s3-simpson","kind":"choice","title":"Reconnaître le paradoxe de Simpson","prompt":"Le paradoxe de Simpson décrit une situation où :","opts":["Une même variable a deux moyennes différentes selon la méthode de calcul","Une relation observée globalement s''inverse ou disparaît lorsqu''on regarde les données groupe par groupe","Un test statistique donne toujours le même résultat quel que soit l''échantillon","Une corrélation négative devient positive en changeant d''unité de mesure"],"answer":1,"hint":"C''est exactement le risque évoqué à propos de l''irrigation et du type de sol.","explain":"C''est la définition même du paradoxe : une tendance visible sur l''ensemble des données peut s''inverser une fois les données séparées par sous-groupe (ici, potentiellement, par type de sol ou par région). C''est pourquoi une corrélation globale se vérifie toujours, quand c''est possible, en la recalculant à l''intérieur de chaque sous-groupe pertinent."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nDécrire population, échantillon, valeurs manquantes et incertitude. Une association ne prouve pas une causalité. Livrable : note de deux pages avec trois constats et leurs limites."}]}'::jsonb, 'lesson', 100, 3
from sms_courses c where c.code = 'DATA-01'
  and not exists (select 1 from sms_lessons x where x.course_id = c.id and x.order_index = 3);

update sms_lessons l set title = 'Semaine 4 — Visualiser pour décider : du graphique au storytelling', content = '{"cells":[{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Un graphique répond à une question, ou il ne sert à rien\n\nCette semaine reprend le jeu de données mobile money du Sénégal — celui nettoyé en semaine 2 — pour le mettre en image. Ce n''est pas un hasard de calendrier : visualiser un fichier qu''on a soi-même nettoyé, et dont on connaît les défauts, évite l''erreur la plus commune du débutant, produire un graphique magnifique sur une donnée encore sale.\n\nAvant de choisir un type de graphique, une seule question compte : **quelle question ce graphique doit-il permettre de répondre ?**\n\n| Question | Type de graphique |\n|---|---|\n| Comment une variable se répartit-elle ? | Histogramme |\n| Comment une valeur évolue-t-elle dans le temps ? | Courbe (line plot) |\n| Comment deux groupes se comparent-ils ? | Barres, boxplot |\n| Comment deux variables numériques sont-elles liées ? | Nuage de points (scatter) |\n| Comment une répartition varie-t-elle géographiquement ? | Carte choroplèthe |\n\nUn graphique choisi pour être « joli » plutôt que pour répondre à l''une de ces questions est ce que la discipline appelle du **chartjunk** — de la décoration qui prend la place de l''information."},{"type":"callout","variant":"warning","title":"Un mensonge visuel fréquent","content":"Un axe des ordonnées qui ne part pas de zéro peut transformer une différence de 3 % en un graphique qui donne l''impression d''un écart de 300 %. Ce n''est pas toujours malhonnête — parfois utile pour voir une variation fine sur une série qui varie peu — mais ça DOIT être signalé, sous peine de tromper, même involontairement, le lecteur pressé qui ne regarde que la forme de la courbe."},{"type":"code","lang":"python","code":"import pandas as pd\n\n# Répartition des transactions mobile money par type, sur un échantillon.\nmm = pd.DataFrame({\n    \"type_transaction\": [\"Retrait\", \"Dépôt\", \"Transfert\", \"Paiement\", \"Recharge\",\n                         \"Retrait\", \"Dépôt\", \"Transfert\", \"Retrait\", \"Dépôt\"],\n    \"montant_xof\": [15000, 25000, 8000, 3000, 1000, 22000, 31000, 12000, 9000, 18000],\n})\n\nrepartition = mm[\"type_transaction\"].value_counts()\nprint(\"Effectif par type :\")\nprint(repartition)\nprint(\"\\nMontant moyen par type :\")\nprint(mm.groupby(\"type_transaction\")[\"montant_xof\"].mean().round(0).sort_values(ascending=False))","output":"Effectif par type :\ntype_transaction\nRetrait      3\nDépôt        3\nTransfert    2\nPaiement     1\nRecharge     1\nName: count, dtype: int64\n\nMontant moyen par type :\ntype_transaction\nDépôt        24666.0\nRetrait      15333.0\nTransfert    10000.0\nPaiement      3000.0\nRecharge      1000.0\nName: value_counts, dtype: float64"},{"type":"md","content":"Ce calcul EST la matière première d''un graphique en barres — mais le graphique n''ajoute rien que le tableau ne dise déjà, sauf la VITESSE de lecture. C''est précisément ce que la visualisation apporte : le même résultat, saisi en une seconde plutôt qu''en lisant cinq lignes de chiffres.\n\n## Construire un Executive Summary\n\nUn décideur ne lit pas un notebook. Il lit, au mieux, une page. La structure qui fonctionne : un **contexte** en une phrase, **3 constats chiffrés** (pas dix), et **une recommandation actionnable**. Exemple, construit sur les vraies proportions du fichier complet :\n\n> Sur 5 000 transactions mobile money analysées dans six villes sénégalaises sur dix-huit mois : (1) les retraits et les dépôts représentent à eux seuls plus de la moitié du volume ; (2) les montants moyens varient fortement d''un type de transaction à l''autre, du simple au vingtuple entre une recharge et un dépôt ; (3) environ 5 % des comptes affichent un statut suspendu ou inactif. **Recommandation** : concentrer le contrôle qualité sur les dépôts et retraits, qui pèsent le plus dans le volume, avant d''investir sur les catégories plus marginales."},{"type":"callout","variant":"tip","title":"Une carte n''est pas obligatoire pour raconter une géographie","content":"Plotly Express permet de tracer une carte choroplèthe (régions colorées selon une valeur) directement depuis un DataFrame. Utile quand le PUBLIC connaît bien la géographie concernée ; un simple graphique en barres trié par région reste souvent plus lisible pour un rapport écrit, où la carte ne s''affiche pas toujours bien à l''impression."},{"type":"resource","title":"Notebook guidé — Semaine 4 : Visualization","url":"/academy/data/notebooks/S4_Visualization.ipynb","desc":"Matplotlib, Seaborn et principes de storytelling appliqués au fichier mobile money nettoyé en semaine 2.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 4 (diapositives)","url":"/academy/data/pptx/S4_Visualization.pptx","desc":"Choix du bon graphique, chartjunk, structure d''un Executive Summary.","provider":"LouisFarm"},{"type":"exercise","id":"s4-quel-graphique-tendance","kind":"choice","title":"Choisir le bon graphique","prompt":"Pour montrer comment le volume mensuel de transactions mobile money a évolué sur dix-huit mois, quel graphique est le plus adapté ?","opts":["Un histogramme","Une courbe (line plot), avec le temps en abscisse","Un nuage de points sans ordre particulier","Un graphique en secteurs (camembert)"],"answer":1,"hint":"« Évolution dans le temps » appelle un axe horizontal chronologique.","explain":"Une courbe temporelle est le choix naturel pour montrer une évolution : le temps en abscisse, la grandeur suivie en ordonnée. Un histogramme montre une répartition, pas une évolution ; un camembert compare des parts d''un tout à un instant donné, pas leur trajectoire."},{"type":"exercise","id":"s4-chartjunk","kind":"text","title":"Nommer le défaut","prompt":"En un mot ou une expression courte : comment appelle-t-on un élément visuel décoratif qui n''apporte aucune information et distrait de la lecture d''un graphique ?","answer":"chartjunk","accept":["surcharge visuelle","decoration inutile","bruit visuel"],"hint":"Le terme est utilisé tel quel dans la leçon, en anglais.","explain":"« Chartjunk » — tout effet visuel (dégradés inutiles, 3D superflue, grilles trop denses) qui prend la place de l''information plutôt que de la servir. Le test simple : si on peut retirer l''élément sans perdre aucune information, c''est du chartjunk."},{"type":"exercise","id":"s4-axe-tronque","kind":"text","title":"Le risque d''un axe tronqué","prompt":"En une expression courte : quel est le principal risque de faire démarrer l''axe des ordonnées d''un graphique en barres à une valeur différente de zéro, sans le signaler ?","answer":"exagerer les differences","accept":["tromper le lecteur","amplifier visuellement l''ecart","fausse impression"],"hint":"Une petite différence réelle peut avoir l''air énorme sur le graphique.","explain":"Le risque est d''exagérer visuellement une différence réelle mais modeste — une variation de quelques pourcents peut avoir l''air spectaculaire si les barres ne partent pas de zéro. Ce n''est pas interdit dans l''absolu, mais ça doit être un choix assumé et signalé, jamais un oubli."},{"type":"exercise","id":"s4-montant-moyen-depot-vs-retrait","kind":"choice","title":"Lire un résultat de groupby","prompt":"D''après le calcul de la cellule de code ci-dessus, quel type de transaction a le montant MOYEN le plus élevé ?","opts":["Retrait","Dépôt","Transfert","Recharge"],"answer":1,"hint":"Regardez le tableau trié par ordre décroissant produit par le code.","explain":"Sur cet échantillon, le dépôt a le montant moyen le plus élevé (24 666 XOF), suivi du retrait (15 333 XOF). Sur le fichier complet, l''ordre des types par montant moyen mérite d''être revérifié — c''est un exercice utile à refaire soi-même dans le notebook fourni."},{"type":"exercise","id":"s4-executive-summary","kind":"choice","title":"La structure d''un Executive Summary","prompt":"Un Executive Summary destiné à un décideur pressé doit contenir, dans l''idéal :","opts":["Un contexte, dix graphiques détaillés, et une conclusion ouverte","Un contexte en une phrase, quelques constats chiffrés, et une recommandation actionnable","Uniquement des graphiques, sans aucun texte","L''intégralité du code Python utilisé pour l''analyse"],"answer":1,"hint":"La contrainte est le TEMPS du lecteur, pas l''exhaustivité de l''analyste.","explain":"La structure qui fonctionne tient sur une page : un contexte bref, un petit nombre de constats chiffrés (trois est un bon repère), et une recommandation que le lecteur peut agir dès la lecture terminée. Le détail technique (code, méthode complète) reste disponible en annexe pour qui veut aller plus loin, mais n''encombre pas le résumé."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nChoisir un destinataire et une décision. Construire trois graphiques avec unités, sources, titres explicites et couleurs lisibles. Livrable : tableau de bord accompagné d’une recommandation."}]}'::jsonb
from sms_courses c where l.course_id = c.id and c.code = 'DATA-01' and l.order_index = 4;

insert into sms_lessons (course_id, title, content, type, points, order_index)
select c.id, 'Semaine 4 — Visualiser pour décider : du graphique au storytelling', '{"cells":[{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Un graphique répond à une question, ou il ne sert à rien\n\nCette semaine reprend le jeu de données mobile money du Sénégal — celui nettoyé en semaine 2 — pour le mettre en image. Ce n''est pas un hasard de calendrier : visualiser un fichier qu''on a soi-même nettoyé, et dont on connaît les défauts, évite l''erreur la plus commune du débutant, produire un graphique magnifique sur une donnée encore sale.\n\nAvant de choisir un type de graphique, une seule question compte : **quelle question ce graphique doit-il permettre de répondre ?**\n\n| Question | Type de graphique |\n|---|---|\n| Comment une variable se répartit-elle ? | Histogramme |\n| Comment une valeur évolue-t-elle dans le temps ? | Courbe (line plot) |\n| Comment deux groupes se comparent-ils ? | Barres, boxplot |\n| Comment deux variables numériques sont-elles liées ? | Nuage de points (scatter) |\n| Comment une répartition varie-t-elle géographiquement ? | Carte choroplèthe |\n\nUn graphique choisi pour être « joli » plutôt que pour répondre à l''une de ces questions est ce que la discipline appelle du **chartjunk** — de la décoration qui prend la place de l''information."},{"type":"callout","variant":"warning","title":"Un mensonge visuel fréquent","content":"Un axe des ordonnées qui ne part pas de zéro peut transformer une différence de 3 % en un graphique qui donne l''impression d''un écart de 300 %. Ce n''est pas toujours malhonnête — parfois utile pour voir une variation fine sur une série qui varie peu — mais ça DOIT être signalé, sous peine de tromper, même involontairement, le lecteur pressé qui ne regarde que la forme de la courbe."},{"type":"code","lang":"python","code":"import pandas as pd\n\n# Répartition des transactions mobile money par type, sur un échantillon.\nmm = pd.DataFrame({\n    \"type_transaction\": [\"Retrait\", \"Dépôt\", \"Transfert\", \"Paiement\", \"Recharge\",\n                         \"Retrait\", \"Dépôt\", \"Transfert\", \"Retrait\", \"Dépôt\"],\n    \"montant_xof\": [15000, 25000, 8000, 3000, 1000, 22000, 31000, 12000, 9000, 18000],\n})\n\nrepartition = mm[\"type_transaction\"].value_counts()\nprint(\"Effectif par type :\")\nprint(repartition)\nprint(\"\\nMontant moyen par type :\")\nprint(mm.groupby(\"type_transaction\")[\"montant_xof\"].mean().round(0).sort_values(ascending=False))","output":"Effectif par type :\ntype_transaction\nRetrait      3\nDépôt        3\nTransfert    2\nPaiement     1\nRecharge     1\nName: count, dtype: int64\n\nMontant moyen par type :\ntype_transaction\nDépôt        24666.0\nRetrait      15333.0\nTransfert    10000.0\nPaiement      3000.0\nRecharge      1000.0\nName: value_counts, dtype: float64"},{"type":"md","content":"Ce calcul EST la matière première d''un graphique en barres — mais le graphique n''ajoute rien que le tableau ne dise déjà, sauf la VITESSE de lecture. C''est précisément ce que la visualisation apporte : le même résultat, saisi en une seconde plutôt qu''en lisant cinq lignes de chiffres.\n\n## Construire un Executive Summary\n\nUn décideur ne lit pas un notebook. Il lit, au mieux, une page. La structure qui fonctionne : un **contexte** en une phrase, **3 constats chiffrés** (pas dix), et **une recommandation actionnable**. Exemple, construit sur les vraies proportions du fichier complet :\n\n> Sur 5 000 transactions mobile money analysées dans six villes sénégalaises sur dix-huit mois : (1) les retraits et les dépôts représentent à eux seuls plus de la moitié du volume ; (2) les montants moyens varient fortement d''un type de transaction à l''autre, du simple au vingtuple entre une recharge et un dépôt ; (3) environ 5 % des comptes affichent un statut suspendu ou inactif. **Recommandation** : concentrer le contrôle qualité sur les dépôts et retraits, qui pèsent le plus dans le volume, avant d''investir sur les catégories plus marginales."},{"type":"callout","variant":"tip","title":"Une carte n''est pas obligatoire pour raconter une géographie","content":"Plotly Express permet de tracer une carte choroplèthe (régions colorées selon une valeur) directement depuis un DataFrame. Utile quand le PUBLIC connaît bien la géographie concernée ; un simple graphique en barres trié par région reste souvent plus lisible pour un rapport écrit, où la carte ne s''affiche pas toujours bien à l''impression."},{"type":"resource","title":"Notebook guidé — Semaine 4 : Visualization","url":"/academy/data/notebooks/S4_Visualization.ipynb","desc":"Matplotlib, Seaborn et principes de storytelling appliqués au fichier mobile money nettoyé en semaine 2.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 4 (diapositives)","url":"/academy/data/pptx/S4_Visualization.pptx","desc":"Choix du bon graphique, chartjunk, structure d''un Executive Summary.","provider":"LouisFarm"},{"type":"exercise","id":"s4-quel-graphique-tendance","kind":"choice","title":"Choisir le bon graphique","prompt":"Pour montrer comment le volume mensuel de transactions mobile money a évolué sur dix-huit mois, quel graphique est le plus adapté ?","opts":["Un histogramme","Une courbe (line plot), avec le temps en abscisse","Un nuage de points sans ordre particulier","Un graphique en secteurs (camembert)"],"answer":1,"hint":"« Évolution dans le temps » appelle un axe horizontal chronologique.","explain":"Une courbe temporelle est le choix naturel pour montrer une évolution : le temps en abscisse, la grandeur suivie en ordonnée. Un histogramme montre une répartition, pas une évolution ; un camembert compare des parts d''un tout à un instant donné, pas leur trajectoire."},{"type":"exercise","id":"s4-chartjunk","kind":"text","title":"Nommer le défaut","prompt":"En un mot ou une expression courte : comment appelle-t-on un élément visuel décoratif qui n''apporte aucune information et distrait de la lecture d''un graphique ?","answer":"chartjunk","accept":["surcharge visuelle","decoration inutile","bruit visuel"],"hint":"Le terme est utilisé tel quel dans la leçon, en anglais.","explain":"« Chartjunk » — tout effet visuel (dégradés inutiles, 3D superflue, grilles trop denses) qui prend la place de l''information plutôt que de la servir. Le test simple : si on peut retirer l''élément sans perdre aucune information, c''est du chartjunk."},{"type":"exercise","id":"s4-axe-tronque","kind":"text","title":"Le risque d''un axe tronqué","prompt":"En une expression courte : quel est le principal risque de faire démarrer l''axe des ordonnées d''un graphique en barres à une valeur différente de zéro, sans le signaler ?","answer":"exagerer les differences","accept":["tromper le lecteur","amplifier visuellement l''ecart","fausse impression"],"hint":"Une petite différence réelle peut avoir l''air énorme sur le graphique.","explain":"Le risque est d''exagérer visuellement une différence réelle mais modeste — une variation de quelques pourcents peut avoir l''air spectaculaire si les barres ne partent pas de zéro. Ce n''est pas interdit dans l''absolu, mais ça doit être un choix assumé et signalé, jamais un oubli."},{"type":"exercise","id":"s4-montant-moyen-depot-vs-retrait","kind":"choice","title":"Lire un résultat de groupby","prompt":"D''après le calcul de la cellule de code ci-dessus, quel type de transaction a le montant MOYEN le plus élevé ?","opts":["Retrait","Dépôt","Transfert","Recharge"],"answer":1,"hint":"Regardez le tableau trié par ordre décroissant produit par le code.","explain":"Sur cet échantillon, le dépôt a le montant moyen le plus élevé (24 666 XOF), suivi du retrait (15 333 XOF). Sur le fichier complet, l''ordre des types par montant moyen mérite d''être revérifié — c''est un exercice utile à refaire soi-même dans le notebook fourni."},{"type":"exercise","id":"s4-executive-summary","kind":"choice","title":"La structure d''un Executive Summary","prompt":"Un Executive Summary destiné à un décideur pressé doit contenir, dans l''idéal :","opts":["Un contexte, dix graphiques détaillés, et une conclusion ouverte","Un contexte en une phrase, quelques constats chiffrés, et une recommandation actionnable","Uniquement des graphiques, sans aucun texte","L''intégralité du code Python utilisé pour l''analyse"],"answer":1,"hint":"La contrainte est le TEMPS du lecteur, pas l''exhaustivité de l''analyste.","explain":"La structure qui fonctionne tient sur une page : un contexte bref, un petit nombre de constats chiffrés (trois est un bon repère), et une recommandation que le lecteur peut agir dès la lecture terminée. Le détail technique (code, méthode complète) reste disponible en annexe pour qui veut aller plus loin, mais n''encombre pas le résumé."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nChoisir un destinataire et une décision. Construire trois graphiques avec unités, sources, titres explicites et couleurs lisibles. Livrable : tableau de bord accompagné d’une recommandation."}]}'::jsonb, 'lesson', 100, 4
from sms_courses c where c.code = 'DATA-01'
  and not exists (select 1 from sms_lessons x where x.course_id = c.id and x.order_index = 4);

update sms_lessons l set title = 'Semaine 5 — Interroger une base relationnelle : SQL, jointures et fonctions de fenêtre', content = '{"cells":[{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Quand un fichier CSV ne suffit plus\n\nUne microfinance ne conserve pas ses données dans un seul fichier : MFB-Bénin, l''établissement de cette semaine, répartit les siennes dans quatre tables reliées entre elles : `clients` (800 personnes), `comptes` (1 195 comptes, certains clients en ayant deux), `transactions` (4 350 mouvements) et `agences` (8 agences). Répondre à « quel est le solde moyen par type de compte » exige de savoir naviguer entre ces quatre tables, pas de tout aplatir dans un seul tableau.\n\nLe vocabulaire de base :\n\n- **clé primaire** — la colonne qui identifie une ligne de façon unique dans sa table (`clients.id`) ;\n- **clé étrangère** — une colonne qui, dans une table, pointe vers la clé primaire d''une autre (`comptes.client_id` pointe vers `clients.id`) ;\n- **jointure** — l''opération qui recombine deux tables via cette relation."},{"type":"code","lang":"python","code":"import sqlite3\n\n# Base en mémoire, avec la même structure que mfb_benin.sqlite (à échelle réduite).\ncon = sqlite3.connect(\":memory:\")\ncon.executescript(\"\"\"\nCREATE TABLE clients (id INTEGER PRIMARY KEY, nom TEXT, region TEXT);\nCREATE TABLE comptes (id INTEGER PRIMARY KEY, client_id INTEGER, type TEXT, solde_actuel INTEGER, statut TEXT);\nINSERT INTO clients VALUES (1,''Adéoti'',''Atlantique''), (2,''Zannou'',''Ouémé''), (3,''Dossou'',''Zou'');\nINSERT INTO comptes VALUES\n  (1,1,''Courant'',86616,''Actif''), (2,1,''Épargne'',169208,''Actif''),\n  (3,2,''Épargne'',204800,''Actif''), (4,3,''Courant'',52000,''Inactif'');\n\"\"\")\n\nrequete = \"\"\"\nSELECT cl.nom, co.type, co.solde_actuel\nFROM clients cl\nJOIN comptes co ON co.client_id = cl.id\nWHERE co.statut = ''Actif''\nORDER BY co.solde_actuel DESC\n\"\"\"\nfor ligne in con.execute(requete):\n    print(ligne)","output":"(''Zannou'', ''Épargne'', 204800)\n(''Adéoti'', ''Épargne'', 169208)\n(''Adéoti'', ''Courant'', 86616)"},{"type":"md","content":"Dossou n''apparaît pas : son unique compte est `Inactif`, exclu par le `WHERE`. C''est le comportement attendu d''un `JOIN` (dit `INNER JOIN`) combiné à un filtre — seules les lignes qui satisfont TOUTES les conditions ressortent.\n\n## GROUP BY, agrégation, et les fonctions de fenêtre\n\n`GROUP BY` regroupe les lignes par valeur commune, pour calculer une agrégation (`COUNT`, `SUM`, `AVG`) par groupe plutôt que sur l''ensemble. `HAVING` filtre APRÈS l''agrégation — là où `WHERE` filtre avant.\n\nLes **fonctions de fenêtre** (`RANK() OVER (...)`, `SUM(...) OVER (...)`) calculent un résultat par ligne, tout en tenant compte d''un groupe de lignes autour d''elle — sans réduire le nombre de lignes, contrairement à `GROUP BY`. C''est ce qu''il faut pour classer des agences par performance tout en gardant chaque agence sur sa propre ligne."},{"type":"code","lang":"python","code":"con.executescript(\"\"\"\nCREATE TABLE agences (ville TEXT, region TEXT, nbr_agents INTEGER);\nINSERT INTO agences VALUES\n  (''Porto-Novo'',''Ouémé'',19), (''Bohicon'',''Zou'',15), (''Cotonou'',''Atlantique'',11),\n  (''Parakou'',''Borgou'',9), (''Natitingou'',''Atacora'',8);\n\"\"\")\n\nrequete = \"\"\"\nSELECT ville, nbr_agents,\n       RANK() OVER (ORDER BY nbr_agents DESC) AS rang_effectif\nFROM agences\nORDER BY rang_effectif\n\"\"\"\nfor ligne in con.execute(requete):\n    print(ligne)","output":"(''Porto-Novo'', 19, 1)\n(''Bohicon'', 15, 2)\n(''Cotonou'', 11, 3)\n(''Parakou'', 9, 4)\n(''Natitingou'', 8, 5)"},{"type":"callout","variant":"real","title":"Sur la base complète (8 agences)","content":"Le classement réel des 8 agences de MFB-Bénin par effectif place Porto-Novo en tête (19 agents), puis Bohicon (15), Cotonou (11), Parakou (9), Natitingou (8), puis Abomey-Calavi et Kandi À ÉGALITÉ à 7 agents chacune (rang 6 tous les deux, RANK() saute alors directement au rang 8 pour Ouidah, 6 agents) — un cas concret où RANK() traite les ex æquo en leur donnant le même rang, sans en \"inventer\" un intermédiaire."},{"type":"md","content":"## Une CTE (Common Table Expression), pour un calcul en deux temps\n\n`WITH nom_temporaire AS (...)` définit une table intermédiaire, utilisable dans la requête qui suit. Utile pour calculer d''abord un agrégat mensuel, puis un cumul dessus — deux étapes, mieux lisibles séparées qu''imbriquées."},{"type":"code","lang":"python","code":"con.executescript(\"\"\"\nCREATE TABLE transactions (compte_id INTEGER, montant INTEGER, mois TEXT);\nINSERT INTO transactions VALUES\n  (1,62648,''2022-01''), (1,24510,''2022-03''), (1,26894,''2022-10''), (1,63947,''2022-11'');\n\"\"\")\n\nrequete = \"\"\"\nWITH mensuel AS (\n  SELECT mois, SUM(montant) AS net\n  FROM transactions WHERE compte_id = 1\n  GROUP BY mois\n)\nSELECT mois, net, SUM(net) OVER (ORDER BY mois) AS cumul\nFROM mensuel ORDER BY mois\n\"\"\"\nfor ligne in con.execute(requete):\n    print(ligne)","output":"(''2022-01'', 62648, 62648)\n(''2022-03'', 24510, 87158)\n(''2022-10'', 26894, 114052)\n(''2022-11'', 63947, 177999)"},{"type":"resource","title":"mfb_benin.sqlite — base complète (4 tables)","url":"/academy/data/datasets/mfb_benin.sqlite","desc":"clients (800), comptes (1 195), transactions (4 350), agences (8). Nécessaire pour le projet de la semaine.","provider":"LouisFarm"},{"type":"resource","title":"Notebook guidé — Semaine 5 : SQL","url":"/academy/data/notebooks/S5_SQL.ipynb","desc":"sqlite3 depuis Python, pandas.read_sql_query, les requêtes complètes sur la base réelle.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 5 (diapositives)","url":"/academy/data/pptx/S5_SQL.pptx","desc":"Modèle relationnel, jointures, GROUP BY/HAVING, fonctions de fenêtre, CTE.","provider":"LouisFarm"},{"type":"exercise","id":"s5-clients-total","kind":"number","title":"Compter dans une table","prompt":"Sur la base complète mfb_benin.sqlite, combien de lignes compte la table « clients » ?","answer":800,"tolerance":0,"hint":"SELECT COUNT(*) FROM clients;","explain":"800 clients. La table « comptes », elle, en compte 1 195 : 395 clients possèdent deux comptes, les 405 autres n''en ont qu''un seul (395×2 + 405×1 = 1 195)."},{"type":"exercise","id":"s5-rang-parakou","kind":"number","title":"Lire un RANK()","prompt":"Dans le classement des 8 agences par nombre d''agents (RANK() OVER (ORDER BY nbr_agents DESC)), quel rang obtient Parakou (9 agents) ?","answer":4,"tolerance":0,"hint":"Porto-Novo (19) est 1er, Bohicon (15) est 2e, Cotonou (11) est 3e.","explain":"Rang 4. L''ordre complet est Porto-Novo (19, rang 1), Bohicon (15, rang 2), Cotonou (11, rang 3), Parakou (9, rang 4), Natitingou (8, rang 5), puis Abomey-Calavi et Kandi ex æquo à 7 agents (rang 6 chacune), et Ouidah (6, rang 8) — RANK() saute le rang 7 après un ex æquo double."},{"type":"exercise","id":"s5-where-vs-having","kind":"choice","title":"WHERE ou HAVING","prompt":"Pour ne garder, après un GROUP BY région, que les régions dont le nombre de clients actifs dépasse 90, quelle clause utiliser ?","opts":["WHERE nombre_clients > 90","HAVING nombre_clients > 90","ORDER BY nombre_clients > 90","GROUP BY nombre_clients > 90"],"answer":1,"hint":"Le filtre porte sur un résultat CALCULÉ par l''agrégation (COUNT), pas sur une colonne brute d''une ligne individuelle.","explain":"HAVING filtre après le calcul de l''agrégat (ici un COUNT par région) — c''est le seul endroit où on peut tester une condition sur le RÉSULTAT d''un GROUP BY. WHERE filtre les lignes individuelles avant tout regroupement, et ne peut donc pas voir un total qui n''existe pas encore à ce stade de la requête."},{"type":"exercise","id":"s5-inner-join-exclut","kind":"text","title":"Ce qu''un INNER JOIN exclut","prompt":"En une expression courte : dans l''exemple de code plus haut, pourquoi le client « Dossou » n''apparaît-il PAS dans le résultat de la requête filtrée sur les comptes Actifs ?","answer":"compte inactif","accept":["son compte est inactif","statut inactif","pas de compte actif"],"hint":"Regardez la ligne INSERT INTO comptes concernant Dossou.","explain":"Le seul compte de Dossou a le statut « Inactif », et la clause WHERE co.statut = ''Actif'' l''exclut du résultat. Un INNER JOIN combiné à un filtre ne garde que les lignes qui satisfont TOUTES les conditions — ici, avoir un compte ET que ce compte soit actif."},{"type":"exercise","id":"s5-cumul-final","kind":"number","title":"Lire un cumul calculé par fenêtre","prompt":"D''après le résultat de la requête CTE + fenêtre ci-dessus, quel est le solde CUMULÉ après le mois « 2022-11 » ?","answer":177999,"tolerance":0,"unit":"FCFA","hint":"C''est la dernière valeur de la colonne « cumul » affichée.","explain":"177 999. Le cumul additionne les montants mensuels dans l''ordre chronologique : 62 648 + 24 510 + 26 894 + 63 947 = 177 999 — exactement ce que fait SUM(net) OVER (ORDER BY mois), sans qu''il soit nécessaire d''écrire une boucle."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nÉcrire cinq requêtes dont une jointure et une agrégation. Contrôler les doublons de clés et la multiplication des lignes après jointure. Livrable : fichier SQL commenté et contrôles de cohérence."}]}'::jsonb
from sms_courses c where l.course_id = c.id and c.code = 'DATA-01' and l.order_index = 5;

insert into sms_lessons (course_id, title, content, type, points, order_index)
select c.id, 'Semaine 5 — Interroger une base relationnelle : SQL, jointures et fonctions de fenêtre', '{"cells":[{"type":"callout","variant":"info","title":"Données pédagogiques synthétiques","content":"Les fichiers générés par utils_louisfarm.py simulent des situations ouest-africaines. Ils ne proviennent pas d’une enquête réelle. Leurs résultats ne décrivent pas les populations de ces pays. Pour une source externe, documenter producteur, date, unités, licence et limites."},{"type":"md","content":"## Quand un fichier CSV ne suffit plus\n\nUne microfinance ne conserve pas ses données dans un seul fichier : MFB-Bénin, l''établissement de cette semaine, répartit les siennes dans quatre tables reliées entre elles : `clients` (800 personnes), `comptes` (1 195 comptes, certains clients en ayant deux), `transactions` (4 350 mouvements) et `agences` (8 agences). Répondre à « quel est le solde moyen par type de compte » exige de savoir naviguer entre ces quatre tables, pas de tout aplatir dans un seul tableau.\n\nLe vocabulaire de base :\n\n- **clé primaire** — la colonne qui identifie une ligne de façon unique dans sa table (`clients.id`) ;\n- **clé étrangère** — une colonne qui, dans une table, pointe vers la clé primaire d''une autre (`comptes.client_id` pointe vers `clients.id`) ;\n- **jointure** — l''opération qui recombine deux tables via cette relation."},{"type":"code","lang":"python","code":"import sqlite3\n\n# Base en mémoire, avec la même structure que mfb_benin.sqlite (à échelle réduite).\ncon = sqlite3.connect(\":memory:\")\ncon.executescript(\"\"\"\nCREATE TABLE clients (id INTEGER PRIMARY KEY, nom TEXT, region TEXT);\nCREATE TABLE comptes (id INTEGER PRIMARY KEY, client_id INTEGER, type TEXT, solde_actuel INTEGER, statut TEXT);\nINSERT INTO clients VALUES (1,''Adéoti'',''Atlantique''), (2,''Zannou'',''Ouémé''), (3,''Dossou'',''Zou'');\nINSERT INTO comptes VALUES\n  (1,1,''Courant'',86616,''Actif''), (2,1,''Épargne'',169208,''Actif''),\n  (3,2,''Épargne'',204800,''Actif''), (4,3,''Courant'',52000,''Inactif'');\n\"\"\")\n\nrequete = \"\"\"\nSELECT cl.nom, co.type, co.solde_actuel\nFROM clients cl\nJOIN comptes co ON co.client_id = cl.id\nWHERE co.statut = ''Actif''\nORDER BY co.solde_actuel DESC\n\"\"\"\nfor ligne in con.execute(requete):\n    print(ligne)","output":"(''Zannou'', ''Épargne'', 204800)\n(''Adéoti'', ''Épargne'', 169208)\n(''Adéoti'', ''Courant'', 86616)"},{"type":"md","content":"Dossou n''apparaît pas : son unique compte est `Inactif`, exclu par le `WHERE`. C''est le comportement attendu d''un `JOIN` (dit `INNER JOIN`) combiné à un filtre — seules les lignes qui satisfont TOUTES les conditions ressortent.\n\n## GROUP BY, agrégation, et les fonctions de fenêtre\n\n`GROUP BY` regroupe les lignes par valeur commune, pour calculer une agrégation (`COUNT`, `SUM`, `AVG`) par groupe plutôt que sur l''ensemble. `HAVING` filtre APRÈS l''agrégation — là où `WHERE` filtre avant.\n\nLes **fonctions de fenêtre** (`RANK() OVER (...)`, `SUM(...) OVER (...)`) calculent un résultat par ligne, tout en tenant compte d''un groupe de lignes autour d''elle — sans réduire le nombre de lignes, contrairement à `GROUP BY`. C''est ce qu''il faut pour classer des agences par performance tout en gardant chaque agence sur sa propre ligne."},{"type":"code","lang":"python","code":"con.executescript(\"\"\"\nCREATE TABLE agences (ville TEXT, region TEXT, nbr_agents INTEGER);\nINSERT INTO agences VALUES\n  (''Porto-Novo'',''Ouémé'',19), (''Bohicon'',''Zou'',15), (''Cotonou'',''Atlantique'',11),\n  (''Parakou'',''Borgou'',9), (''Natitingou'',''Atacora'',8);\n\"\"\")\n\nrequete = \"\"\"\nSELECT ville, nbr_agents,\n       RANK() OVER (ORDER BY nbr_agents DESC) AS rang_effectif\nFROM agences\nORDER BY rang_effectif\n\"\"\"\nfor ligne in con.execute(requete):\n    print(ligne)","output":"(''Porto-Novo'', 19, 1)\n(''Bohicon'', 15, 2)\n(''Cotonou'', 11, 3)\n(''Parakou'', 9, 4)\n(''Natitingou'', 8, 5)"},{"type":"callout","variant":"real","title":"Sur la base complète (8 agences)","content":"Le classement réel des 8 agences de MFB-Bénin par effectif place Porto-Novo en tête (19 agents), puis Bohicon (15), Cotonou (11), Parakou (9), Natitingou (8), puis Abomey-Calavi et Kandi À ÉGALITÉ à 7 agents chacune (rang 6 tous les deux, RANK() saute alors directement au rang 8 pour Ouidah, 6 agents) — un cas concret où RANK() traite les ex æquo en leur donnant le même rang, sans en \"inventer\" un intermédiaire."},{"type":"md","content":"## Une CTE (Common Table Expression), pour un calcul en deux temps\n\n`WITH nom_temporaire AS (...)` définit une table intermédiaire, utilisable dans la requête qui suit. Utile pour calculer d''abord un agrégat mensuel, puis un cumul dessus — deux étapes, mieux lisibles séparées qu''imbriquées."},{"type":"code","lang":"python","code":"con.executescript(\"\"\"\nCREATE TABLE transactions (compte_id INTEGER, montant INTEGER, mois TEXT);\nINSERT INTO transactions VALUES\n  (1,62648,''2022-01''), (1,24510,''2022-03''), (1,26894,''2022-10''), (1,63947,''2022-11'');\n\"\"\")\n\nrequete = \"\"\"\nWITH mensuel AS (\n  SELECT mois, SUM(montant) AS net\n  FROM transactions WHERE compte_id = 1\n  GROUP BY mois\n)\nSELECT mois, net, SUM(net) OVER (ORDER BY mois) AS cumul\nFROM mensuel ORDER BY mois\n\"\"\"\nfor ligne in con.execute(requete):\n    print(ligne)","output":"(''2022-01'', 62648, 62648)\n(''2022-03'', 24510, 87158)\n(''2022-10'', 26894, 114052)\n(''2022-11'', 63947, 177999)"},{"type":"resource","title":"mfb_benin.sqlite — base complète (4 tables)","url":"/academy/data/datasets/mfb_benin.sqlite","desc":"clients (800), comptes (1 195), transactions (4 350), agences (8). Nécessaire pour le projet de la semaine.","provider":"LouisFarm"},{"type":"resource","title":"Notebook guidé — Semaine 5 : SQL","url":"/academy/data/notebooks/S5_SQL.ipynb","desc":"sqlite3 depuis Python, pandas.read_sql_query, les requêtes complètes sur la base réelle.","provider":"LouisFarm"},{"type":"resource","title":"Support de la semaine 5 (diapositives)","url":"/academy/data/pptx/S5_SQL.pptx","desc":"Modèle relationnel, jointures, GROUP BY/HAVING, fonctions de fenêtre, CTE.","provider":"LouisFarm"},{"type":"exercise","id":"s5-clients-total","kind":"number","title":"Compter dans une table","prompt":"Sur la base complète mfb_benin.sqlite, combien de lignes compte la table « clients » ?","answer":800,"tolerance":0,"hint":"SELECT COUNT(*) FROM clients;","explain":"800 clients. La table « comptes », elle, en compte 1 195 : 395 clients possèdent deux comptes, les 405 autres n''en ont qu''un seul (395×2 + 405×1 = 1 195)."},{"type":"exercise","id":"s5-rang-parakou","kind":"number","title":"Lire un RANK()","prompt":"Dans le classement des 8 agences par nombre d''agents (RANK() OVER (ORDER BY nbr_agents DESC)), quel rang obtient Parakou (9 agents) ?","answer":4,"tolerance":0,"hint":"Porto-Novo (19) est 1er, Bohicon (15) est 2e, Cotonou (11) est 3e.","explain":"Rang 4. L''ordre complet est Porto-Novo (19, rang 1), Bohicon (15, rang 2), Cotonou (11, rang 3), Parakou (9, rang 4), Natitingou (8, rang 5), puis Abomey-Calavi et Kandi ex æquo à 7 agents (rang 6 chacune), et Ouidah (6, rang 8) — RANK() saute le rang 7 après un ex æquo double."},{"type":"exercise","id":"s5-where-vs-having","kind":"choice","title":"WHERE ou HAVING","prompt":"Pour ne garder, après un GROUP BY région, que les régions dont le nombre de clients actifs dépasse 90, quelle clause utiliser ?","opts":["WHERE nombre_clients > 90","HAVING nombre_clients > 90","ORDER BY nombre_clients > 90","GROUP BY nombre_clients > 90"],"answer":1,"hint":"Le filtre porte sur un résultat CALCULÉ par l''agrégation (COUNT), pas sur une colonne brute d''une ligne individuelle.","explain":"HAVING filtre après le calcul de l''agrégat (ici un COUNT par région) — c''est le seul endroit où on peut tester une condition sur le RÉSULTAT d''un GROUP BY. WHERE filtre les lignes individuelles avant tout regroupement, et ne peut donc pas voir un total qui n''existe pas encore à ce stade de la requête."},{"type":"exercise","id":"s5-inner-join-exclut","kind":"text","title":"Ce qu''un INNER JOIN exclut","prompt":"En une expression courte : dans l''exemple de code plus haut, pourquoi le client « Dossou » n''apparaît-il PAS dans le résultat de la requête filtrée sur les comptes Actifs ?","answer":"compte inactif","accept":["son compte est inactif","statut inactif","pas de compte actif"],"hint":"Regardez la ligne INSERT INTO comptes concernant Dossou.","explain":"Le seul compte de Dossou a le statut « Inactif », et la clause WHERE co.statut = ''Actif'' l''exclut du résultat. Un INNER JOIN combiné à un filtre ne garde que les lignes qui satisfont TOUTES les conditions — ici, avoir un compte ET que ce compte soit actif."},{"type":"exercise","id":"s5-cumul-final","kind":"number","title":"Lire un cumul calculé par fenêtre","prompt":"D''après le résultat de la requête CTE + fenêtre ci-dessus, quel est le solde CUMULÉ après le mois « 2022-11 » ?","answer":177999,"tolerance":0,"unit":"FCFA","hint":"C''est la dernière valeur de la colonne « cumul » affichée.","explain":"177 999. Le cumul additionne les montants mensuels dans l''ordre chronologique : 62 648 + 24 510 + 26 894 + 63 947 = 177 999 — exactement ce que fait SUM(net) OVER (ORDER BY mois), sans qu''il soit nécessaire d''écrire une boucle."},{"type":"md","content":"## Atelier professionnel — livrable à conserver\n\nÉcrire cinq requêtes dont une jointure et une agrégation. Contrôler les doublons de clés et la multiplication des lignes après jointure. Livrable : fichier SQL commenté et contrôles de cohérence."}]}'::jsonb, 'lesson', 100, 5
from sms_courses c where c.code = 'DATA-01'
  and not exists (select 1 from sms_lessons x where x.course_id = c.id and x.order_index = 5);
